package com.asgardians;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.gameval.ItemID;

/**
 * Works out what the member is doing from their own client, for the Members page: "Theatre of Blood", "Vorkath",
 * "Slayer · Abyssal demon", "Mining", "Grand Exchange". Only the member's own state is used, and it's only sent with
 * "Share my activity" on. The plugin calls {@link #describe} from the client thread.
 */
final class ActivityTracker
{
	static final String RAIDS = "Raids";
	static final String BOSSING = "Bossing";
	static final String SKILLING = "Skilling";
	static final String OTHER = "Other";

	static final String COX = "Chambers of Xeric";
	static final String TOB = "Theatre of Blood";
	static final String TOA = "Tombs of Amascut";
	static final String GE = "Grand Exchange";
	static final String BANK = "Banking";

	/** A fight or a skill counts for this long after the last hit or XP drop. */
	static final int RECENT_TICKS = 50;
	/** The Grand Exchange's region. */
	static final int GE_REGION = 12598;

	/** Boss names (lowercase) to what they're shown as; raid bosses show their raid. */
	private static final Map<String, String> BOSSES = new HashMap<>();
	/** Activities to an item whose picture stands for them. */
	private static final Map<String, Integer> ICONS = new HashMap<>();

	static
	{
		for (String b : new String[]{"great olm", "tekton", "vasa nistirio", "vespula", "muttadile", "vanguard", "skeletal mystic",
			"lizardman shaman", "ice demon", "guardian", "deathly ranger", "deathly mage"})
		{
			BOSSES.put(b, COX);
		}
		for (String b : new String[]{"the maiden of sugadinti", "pestilent bloat", "nylocas vasilias", "sotetseg", "xarpus",
			"verzik vitur", "nylocas hagios", "nylocas toxobolos", "nylocas ischyros"})
		{
			BOSSES.put(b, TOB);
		}
		for (String b : new String[]{"akkha", "ba-ba", "kephri", "zebak", "tumeken's warden", "elidinis' warden", "obelisk"})
		{
			BOSSES.put(b, TOA);
		}
		for (String b : new String[]{"vorkath", "zulrah", "nex", "general graardor", "k'ril tsutsaroth", "kree'arra",
			"commander zilyana", "corporeal beast", "cerberus", "alchemical hydra", "phantom muspah", "the leviathan",
			"duke sucellus", "vardorvis", "the whisperer", "sarachnis", "kalphite queen", "king black dragon", "giant mole",
			"abyssal sire", "kraken", "thermonuclear smoke devil", "callisto", "vet'ion", "venenatis", "artio", "calvar'ion",
			"spindel", "chaos elemental", "scorpia", "the nightmare", "phosani's nightmare", "zalcano", "araxxor",
			"the hueycoatl", "amoxliatl", "scurrius", "yama", "skotizo", "hespori", "tormented demon", "bryophyta", "obor",
			"mimic", "crazy archaeologist", "chaos fanatic", "deranged archaeologist", "the gauntlet"})
		{
			BOSSES.put(b, b.substring(0, 1).toUpperCase(Locale.UK) + b.substring(1));
		}
		BOSSES.put("dagannoth rex", "Dagannoth Kings");
		BOSSES.put("dagannoth prime", "Dagannoth Kings");
		BOSSES.put("dagannoth supreme", "Dagannoth Kings");
		BOSSES.put("dusk", "Grotesque Guardians");
		BOSSES.put("dawn", "Grotesque Guardians");
		BOSSES.put("branda the fire queen", "Royal Titans");
		BOSSES.put("eldric the ice king", "Royal Titans");
		BOSSES.put("sol heredit", "Fortis Colosseum");
		BOSSES.put("tztok-jad", "TzHaar Fight Cave");
		BOSSES.put("tzkal-zuk", "The Inferno");
		BOSSES.put("crystalline hunllef", "The Gauntlet");
		BOSSES.put("corrupted hunllef", "The Corrupted Gauntlet");
		// Proper names keep their capitals.
		BOSSES.put("k'ril tsutsaroth", "K'ril Tsutsaroth");
		BOSSES.put("kree'arra", "Kree'arra");
		BOSSES.put("commander zilyana", "Commander Zilyana");
		BOSSES.put("general graardor", "General Graardor");
		BOSSES.put("corporeal beast", "Corporeal Beast");
		BOSSES.put("alchemical hydra", "Alchemical Hydra");
		BOSSES.put("phantom muspah", "Phantom Muspah");
		BOSSES.put("the leviathan", "The Leviathan");
		BOSSES.put("duke sucellus", "Duke Sucellus");
		BOSSES.put("the whisperer", "The Whisperer");
		BOSSES.put("kalphite queen", "Kalphite Queen");
		BOSSES.put("king black dragon", "King Black Dragon");
		BOSSES.put("giant mole", "Giant Mole");
		BOSSES.put("abyssal sire", "Abyssal Sire");
		BOSSES.put("thermonuclear smoke devil", "Thermonuclear Smoke Devil");
		BOSSES.put("chaos elemental", "Chaos Elemental");
		BOSSES.put("the nightmare", "The Nightmare");
		BOSSES.put("phosani's nightmare", "Phosani's Nightmare");
		BOSSES.put("the hueycoatl", "The Hueycoatl");
		BOSSES.put("tormented demon", "Tormented Demons");
		BOSSES.put("crazy archaeologist", "Crazy Archaeologist");
		BOSSES.put("chaos fanatic", "Chaos Fanatic");
		BOSSES.put("deranged archaeologist", "Deranged Archaeologist");
		BOSSES.put("the gauntlet", "The Gauntlet");

		ICONS.put(COX, ItemID.OLMPET);
		ICONS.put(TOB, ItemID.VERZIKPET);
		ICONS.put(TOA, ItemID.WARDENPET_TUMEKEN);
		ICONS.put("Vorkath", ItemID.VORKATHPET);
		ICONS.put("Zulrah", ItemID.SNAKEPET);
		ICONS.put("Nex", ItemID.NEXPET);
		ICONS.put("General Graardor", ItemID.BANDOSPET);
		ICONS.put("Kree'arra", ItemID.ARMADYLPET);
		ICONS.put("Commander Zilyana", ItemID.SARADOMINPET);
		ICONS.put("K'ril Tsutsaroth", ItemID.ZAMORAKPET);
		ICONS.put("Corporeal Beast", ItemID.COREPET);
		ICONS.put("Cerberus", ItemID.HELL_PET);
		ICONS.put("Alchemical Hydra", ItemID.HYDRAPET);
		ICONS.put("Kalphite Queen", ItemID.KQPET_WALKING);
		ICONS.put("Giant Mole", ItemID.MOLEPET);
		ICONS.put("Kraken", ItemID.KRAKENPET);
		ICONS.put("Abyssal Sire", ItemID.ABYSSALSIRE_PET);
		ICONS.put("Grotesque Guardians", ItemID.DAWNPET);
		ICONS.put("The Nightmare", ItemID.NIGHTMAREPET);
		ICONS.put("Phosani's Nightmare", ItemID.NIGHTMAREPET);
		ICONS.put("The Whisperer", ItemID.WHISPERERPET);
		ICONS.put("The Hueycoatl", ItemID.HUEYPET);
		ICONS.put("Yama", ItemID.YAMAPET);
		ICONS.put("Skotizo", ItemID.SKOTIZOPET);
		ICONS.put("TzHaar Fight Cave", ItemID.TZHAAR_CAPE_FIRE);
		ICONS.put("The Inferno", ItemID.INFERNAL_CAPE);
		ICONS.put("Tempoross", ItemID.TEMPOROSSPET);
		ICONS.put(GE, ItemID.COINS);
		ICONS.put(BANK, ItemID.COINS);
		ICONS.put("Slayer", ItemID.SLAYER_HELM);
		ICONS.put("Mining", ItemID.RUNE_PICKAXE);
		ICONS.put("Woodcutting", ItemID.RUNE_AXE);
		ICONS.put("Fishing", ItemID.LOBSTER_POT);
		ICONS.put("Smithing", ItemID.HAMMER);
		ICONS.put("Fletching", ItemID.KNIFE);
		ICONS.put("Firemaking", ItemID.TINDERBOX);
		ICONS.put("Crafting", ItemID.CHISEL);
		ICONS.put("Herblore", ItemID.PESTLE_AND_MORTAR);
		ICONS.put("Runecraft", ItemID.BLANKRUNE_HIGH);
		ICONS.put("Farming", ItemID.RAKE);
		ICONS.put("Prayer", ItemID.BONES);
		ICONS.put("Agility", ItemID.GRACEFUL_HOOD);
	}

	private ActivityTracker()
	{
	}

	/** What the member's client sees right now. Ticks are game ticks; -1 means never. */
	@lombok.Value
	static class Snapshot
	{
		int tick;
		boolean inCox;
		boolean inTob;
		/** The NPC last fought, and on which tick. */
		String target;
		int targetTick;
		/** The member's Slayer task count, so fights on task show as Slayer. */
		int slayerCount;
		/** The skill that last gave XP outside combat, and on which tick. */
		String skill;
		int skillTick;
		boolean bankOpen;
		int region;
	}

	/** What the member is doing, or null when nothing in particular (shown as just "Online"). */
	static String describe(Snapshot s)
	{
		if (s.isInCox())
		{
			return COX;
		}
		if (s.isInTob())
		{
			return TOB;
		}
		boolean fighting = s.getTarget() != null && s.getTargetTick() >= 0 && s.getTick() - s.getTargetTick() <= RECENT_TICKS;
		if (fighting)
		{
			String boss = boss(s.getTarget());
			if (boss != null)
			{
				return boss;
			}
			if (s.getSlayerCount() > 0)
			{
				return "Slayer · " + s.getTarget();
			}
		}
		boolean skilling = s.getSkill() != null && s.getSkillTick() >= 0 && s.getTick() - s.getSkillTick() <= RECENT_TICKS;
		if (skilling)
		{
			return s.getSkill();
		}
		if (s.isBankOpen())
		{
			return s.getRegion() == GE_REGION ? GE : BANK;
		}
		if (s.getRegion() == GE_REGION)
		{
			return GE;
		}
		if (fighting)
		{
			return "Combat · " + s.getTarget();
		}
		return null;
	}

	/** The boss an NPC name belongs to, or null when it isn't one. */
	static String boss(String npc)
	{
		return npc == null ? null : BOSSES.get(npc.toLowerCase(Locale.UK).trim());
	}

	/** Raids, Bossing, Skilling or Other, for the Members page's filter. */
	static String category(String activity)
	{
		if (activity == null)
		{
			return OTHER;
		}
		if (activity.startsWith(COX) || activity.startsWith(TOB) || activity.startsWith(TOA))
		{
			return RAIDS;
		}
		if (activity.startsWith("Slayer") || activity.startsWith("Combat") || BOSSES.containsValue(activity)
			|| activity.equals("Fortis Colosseum") || activity.equals("The Inferno") || activity.equals("TzHaar Fight Cave"))
		{
			return BOSSING;
		}
		for (net.runelite.api.Skill skill : net.runelite.api.Skill.values())
		{
			if (activity.startsWith(skill.getName()))
			{
				return SKILLING;
			}
		}
		return activity.equals("Tempoross") || activity.equals("Wintertodt") ? SKILLING : OTHER;
	}

	/** An item whose picture stands for the activity, or null. */
	static Integer icon(String activity)
	{
		if (activity == null)
		{
			return null;
		}
		Integer id = ICONS.get(activity);
		if (id == null)
		{
			int dot = activity.indexOf(" · ");
			id = dot > 0 ? ICONS.get(activity.substring(0, dot)) : null;
		}
		return id;
	}
}

package com.asgardians;

/** Works out which website the plugin talks to. The -Dasgardians.apiUrl launch flag wins over the config field. */
final class ApiAddress
{
	static final String LAUNCH_FLAG = "asgardians.apiUrl";

	private ApiAddress()
	{
	}

	static String resolve(String configured)
	{
		String flag = System.getProperty(LAUNCH_FLAG);
		String address = flag != null && !flag.isBlank() ? flag : configured;
		if (address == null || address.isBlank())
		{
			address = AsgardiansConfig.DEFAULT_API_ADDRESS;
		}
		address = address.trim();
		while (address.endsWith("/"))
		{
			address = address.substring(0, address.length() - 1);
		}
		return address;
	}

	static boolean isDefault(String address)
	{
		return AsgardiansConfig.DEFAULT_API_ADDRESS.equalsIgnoreCase(address);
	}

	static boolean isInsecure(String address)
	{
		return address.toLowerCase().startsWith("http://");
	}

	static boolean fromLaunchFlag()
	{
		String flag = System.getProperty(LAUNCH_FLAG);
		return flag != null && !flag.isBlank();
	}
}

package com.asgardians;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Talks to /api/v1/plugin/* on the configured address. Every call is asynchronous and reports back on OkHttp's thread.
 */
@Slf4j
class ApiClient
{
	static final String PLUGIN_VERSION = "0.1.0";
	static final String INSTALL_KEY_HEADER = "X-Install-Key";

	private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");
	private static final MediaType PNG = MediaType.get("image/png");

	@Value
	static class RegisterResult
	{
		/** HTTP status, or 0 when the server couldn't be reached. */
		int status;
		String installKey;
		String displayName;
		/** True when the server accepted the RSN but holds its records for staff review (account hash mismatch). */
		boolean held;
		String error;
	}

	@Value
	static class SubmitResult
	{
		int status;
		String error;

		boolean ok()
		{
			return status >= 200 && status < 300;
		}
	}

	private final OkHttpClient http;
	private final Gson gson;

	ApiClient(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	void register(String address, String rsn, long accountHash, String accountType, Consumer<RegisterResult> done)
	{
		JsonObject body = new JsonObject();
		body.addProperty("rsn", rsn);
		body.addProperty("accountHash", accountHash);
		body.addProperty("accountType", accountType);
		body.addProperty("pluginVersion", PLUGIN_VERSION);
		Request request = new Request.Builder()
			.url(endpoint(address, "register"))
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				done.accept(new RegisterResult(0, null, null, false, e.getMessage()));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody responseBody = response.body())
				{
					String text = responseBody != null ? responseBody.string() : "";
					if (!response.isSuccessful())
					{
						done.accept(new RegisterResult(response.code(), null, null, false, errorFrom(text)));
						return;
					}
					JsonObject json = gson.fromJson(text, JsonObject.class);
					String key = json != null && json.has("installKey") ? json.get("installKey").getAsString() : null;
					String name = json != null && json.has("displayName") ? json.get("displayName").getAsString() : rsn;
					boolean held = json != null && json.has("held") && json.get("held").getAsBoolean();
					done.accept(key == null
						? new RegisterResult(response.code(), null, null, false, "No install key in the response")
						: new RegisterResult(response.code(), key, name, held, null));
				}
				catch (IOException | JsonParseException | IllegalStateException e)
				{
					done.accept(new RegisterResult(response.code(), null, null, false, "Bad response: " + e.getMessage()));
				}
			}
		});
	}

	void fetchSettings(String address, Consumer<ServerSettings> done)
	{
		Request request = new Request.Builder().url(endpoint(address, "config")).get().build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Asgardians config fetch failed: {}", e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody responseBody = response.body())
				{
					if (response.isSuccessful() && responseBody != null)
					{
						ServerSettings settings = gson.fromJson(responseBody.string(), ServerSettings.class);
						if (settings != null)
						{
							if (settings.getScreenshots() == null)
							{
								settings.setScreenshots(new ServerSettings.Screenshots());
							}
							done.accept(settings);
						}
					}
				}
				catch (IOException | JsonParseException e)
				{
					log.debug("Asgardians config unreadable: {}", e.getMessage());
				}
			}
		});
	}

	/**
	 * Sends a batch of records. With no screenshots the body is JSON; with screenshots it is multipart, with the JSON in a
	 * "payload" part and each image in a "screenshot_<record id>" part.
	 */
	void submitRecords(String address, String installKey, AccountInfo account, List<Record> records,
		Map<String, byte[]> screenshots, Consumer<SubmitResult> done)
	{
		JsonObject body = new JsonObject();
		body.add("account", gson.toJsonTree(account));
		body.addProperty("pluginVersion", PLUGIN_VERSION);
		body.add("records", gson.toJsonTree(records));
		String json = gson.toJson(body);

		RequestBody requestBody;
		if (screenshots.isEmpty())
		{
			requestBody = RequestBody.create(JSON, json);
		}
		else
		{
			MultipartBody.Builder multipart = new MultipartBody.Builder().setType(MultipartBody.FORM)
				.addFormDataPart("payload", null, RequestBody.create(JSON, json));
			screenshots.forEach((id, png) ->
				multipart.addFormDataPart("screenshot_" + id, id + ".png", RequestBody.create(PNG, png)));
			requestBody = multipart.build();
		}

		Request request = new Request.Builder()
			.url(endpoint(address, "records"))
			.header(INSTALL_KEY_HEADER, installKey)
			.header("Idempotency-Key", idempotencyKey(records))
			.post(requestBody)
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				done.accept(new SubmitResult(0, e.getMessage()));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody responseBody = response.body())
				{
					String text = responseBody != null ? responseBody.string() : "";
					done.accept(new SubmitResult(response.code(), response.isSuccessful() ? null : errorFrom(text)));
				}
				catch (IOException e)
				{
					done.accept(new SubmitResult(response.code(), e.getMessage()));
				}
			}
		});
	}

	/** Sends every PB RuneLite has stored for this account. The server upserts each by key. */
	void syncPersonalBests(String address, String installKey, AccountInfo account, List<PersonalBest> pbs,
		Consumer<SubmitResult> done)
	{
		JsonObject body = new JsonObject();
		body.add("account", gson.toJsonTree(account));
		body.addProperty("pluginVersion", PLUGIN_VERSION);
		body.add("pbs", gson.toJsonTree(pbs));
		put(endpoint(address, "pbs/full"), installKey, gson.toJson(body), done);
	}

	/** Sends every obtained collection log item. The server replaces the member's collection log with it. */
	void syncCollectionLog(String address, String installKey, AccountInfo account, List<ClogCapture.Item> items,
		int obtained, int total, Consumer<SubmitResult> done)
	{
		JsonObject body = new JsonObject();
		body.add("account", gson.toJsonTree(account));
		body.addProperty("pluginVersion", PLUGIN_VERSION);
		body.addProperty("obtained", obtained);
		body.addProperty("total", total);
		body.add("items", gson.toJsonTree(items));
		put(endpoint(address, "clog/full"), installKey, gson.toJson(body), done);
	}

	@Value
	static class GetResult<T>
	{
		int status;
		T body;
		String error;

		boolean ok()
		{
			return status >= 200 && status < 300 && body != null;
		}
	}

	/** A read-only call, parsed into the given class. Build the URL with {@link #endpoint}. */
	<T> void get(HttpUrl url, String installKey, Class<T> type, Consumer<GetResult<T>> done)
	{
		Request request = new Request.Builder().url(url).header(INSTALL_KEY_HEADER, installKey).get().build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				done.accept(new GetResult<>(0, null, e.getMessage()));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody responseBody = response.body())
				{
					String text = responseBody != null ? responseBody.string() : "";
					if (!response.isSuccessful())
					{
						done.accept(new GetResult<>(response.code(), null, errorFrom(text)));
						return;
					}
					done.accept(new GetResult<>(response.code(), gson.fromJson(text, type), null));
				}
				catch (IOException | JsonParseException e)
				{
					done.accept(new GetResult<>(response.code(), null, "Bad response: " + e.getMessage()));
				}
			}
		});
	}

	/** Signs the member up for an event with their form answers. */
	void signUp(String address, String installKey, String eventId, java.util.Map<String, Object> answers,
		Consumer<GetResult<ClanData.SignupResult>> done)
	{
		JsonObject body = new JsonObject();
		body.add("answers", gson.toJsonTree(answers));
		send(new Request.Builder().url(endpoint(address, "events/" + eventId + "/signup"))
			.header(INSTALL_KEY_HEADER, installKey)
			.post(RequestBody.create(JSON, gson.toJson(body))).build(), ClanData.SignupResult.class, done);
	}

	/** Withdraws the member from an event. */
	/** A group finder action (create, join, leave, close, kick or check in). Every reply is the whole group list. */
	void groups(String address, String installKey, String path, JsonObject body, Consumer<GetResult<ClanData.GroupList>> done)
	{
		send(new Request.Builder().url(endpoint(address, path))
			.header(INSTALL_KEY_HEADER, installKey)
			.post(RequestBody.create(JSON, gson.toJson(body))).build(), ClanData.GroupList.class, done);
	}

	/** Puts a drop that fits several tiles on the one the member picked. */
	void chooseTile(String address, String installKey, String eventId, String dropId, String tileId,
		Consumer<GetResult<ClanData.TileChoice>> done)
	{
		JsonObject body = new JsonObject();
		body.addProperty("tileId", tileId);
		send(new Request.Builder().url(endpoint(address, "events/" + eventId + "/drops/" + dropId + "/tile"))
			.header(INSTALL_KEY_HEADER, installKey)
			.post(RequestBody.create(JSON, gson.toJson(body))).build(), ClanData.TileChoice.class, done);
	}

	void withdraw(String address, String installKey, String eventId, Consumer<GetResult<ClanData.SignupResult>> done)
	{
		send(new Request.Builder().url(endpoint(address, "events/" + eventId + "/signup"))
			.header(INSTALL_KEY_HEADER, installKey)
			.delete().build(), ClanData.SignupResult.class, done);
	}

	/** POSTs a JSON body and reads the reply as {@code type}. */
	<T> void post(HttpUrl url, String installKey, JsonObject body, Class<T> type, Consumer<GetResult<T>> done)
	{
		send(new Request.Builder().url(url)
			.header(INSTALL_KEY_HEADER, installKey)
			.post(RequestBody.create(JSON, gson.toJson(body))).build(), type, done);
	}

	private <T> void send(Request request, Class<T> type, Consumer<GetResult<T>> done)
	{
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				done.accept(new GetResult<>(0, null, e.getMessage()));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody responseBody = response.body())
				{
					String text = responseBody != null ? responseBody.string() : "";
					if (!response.isSuccessful())
					{
						done.accept(new GetResult<>(response.code(), null, errorFrom(text)));
						return;
					}
					T body = text.isEmpty() ? null : gson.fromJson(text, type);
					done.accept(new GetResult<>(response.code(), body, null));
				}
				catch (IOException | JsonParseException e)
				{
					done.accept(new GetResult<>(response.code(), null, "Bad response: " + e.getMessage()));
				}
			}
		});
	}

	private void put(HttpUrl url, String installKey, String json, Consumer<SubmitResult> done)
	{
		Request request = new Request.Builder()
			.url(url)
			.header(INSTALL_KEY_HEADER, installKey)
			.put(RequestBody.create(JSON, json))
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				done.accept(new SubmitResult(0, e.getMessage()));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody responseBody = response.body())
				{
					String text = responseBody != null ? responseBody.string() : "";
					done.accept(new SubmitResult(response.code(), response.isSuccessful() ? null : errorFrom(text)));
				}
				catch (IOException e)
				{
					done.accept(new SubmitResult(response.code(), e.getMessage()));
				}
			}
		});
	}

	static HttpUrl endpoint(String address, String path)
	{
		HttpUrl base = HttpUrl.parse(address);
		if (base == null)
		{
			throw new IllegalArgumentException("Not a valid API address: " + address);
		}
		return base.newBuilder().addPathSegments("api/v1/plugin/" + path).build();
	}

	/** The same batch always gets the same key, so a retry after a timeout is recognised by the server. */
	static String idempotencyKey(List<Record> records)
	{
		StringBuilder ids = new StringBuilder();
		for (Record record : records)
		{
			ids.append(record.getId()).append(',');
		}
		return sha256(ids.toString());
	}

	static String sha256(String text)
	{
		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8));
			StringBuilder hex = new StringBuilder();
			for (byte b : digest)
			{
				hex.append(String.format("%02x", b));
			}
			return hex.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			throw new IllegalStateException(e);
		}
	}

	private String errorFrom(String text)
	{
		try
		{
			JsonObject json = gson.fromJson(text, JsonObject.class);
			if (json != null && json.has("error"))
			{
				return json.get("error").getAsString();
			}
		}
		catch (JsonParseException | IllegalStateException ignored)
		{
		}
		return text.length() > 200 ? text.substring(0, 200) : text;
	}

	@Value
	static class AccountInfo
	{
		long hash;
		String rsn;
		String type;
	}
}

package com.asgardians;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import lombok.Value;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.util.QuantityFormatter;

/**
 * The "!asg" chat commands. Like the Chat Commands plugin, whoever types one sends it as normal chat, and every clanmate
 * running the plugin sees the line replaced with the answer on their own screen. Clan-wide answers come from what the
 * reader's plugin has already loaded; answers about the player who typed it come from their clan profile.
 * Pure, so it can be tested.
 */
final class AsgCommands
{
	static final String PREFIX = "!asg";

	/** Answers about the player who typed the command, from their clan profile. */
	static final List<String> PERSONAL = List.of("credit", "clancredit", "rank", "ehb", "ehp", "profile", "eggs");
	static final List<String> PERIODS = List.of("week", "month", "year", "all");
	private static final int TOP = 3;

	private AsgCommands()
	{
	}

	/** What the reader's plugin has loaded. Any part may be null or empty. */
	@Value
	static class Clan
	{
		ClanData.GroupList groups;
		List<ClanData.GroupActivity> activities;
		ClanView view;
		/** Leaderboards by period: week, month, year, all. */
		Map<String, List<ClanData.Leaderboard>> boards;
		ClanData.StatsFeed stats;
		Instant now;
	}

	/** The command word, lower case: "groups" for "!asg Groups week". Empty for "!asg" alone. */
	static String word(String args)
	{
		String[] parts = args.trim().split("\\s+", 2);
		return parts[0].toLowerCase(Locale.UK);
	}

	/** What follows the command word: "week" for "!asg drops week". */
	static String rest(String args)
	{
		String[] parts = args.trim().split("\\s+", 2);
		return parts.length > 1 ? parts[1].trim() : "";
	}

	static boolean personal(String word)
	{
		return PERSONAL.contains(word);
	}

	/**
	 * The answer to a clan-wide command, or null to leave the line as typed (an unknown command, or nothing loaded).
	 *
	 * @param args   what followed "!asg"
	 * @param sender the RSN of whoever typed it
	 */
	static String answer(String args, String sender, Clan clan)
	{
		String word = word(args);
		String rest = rest(args);
		switch (word)
		{
			case "":
			case "help":
				return help();
			case "groups":
			case "group":
				return groups(clan);
			case "events":
			case "event":
				return events(clan);
			case "bingo":
				return bingo(clan);
			case "sotw":
				return competition(clan, "sotw", "Skill of the Week");
			case "botw":
				return competition(clan, "botw", "Boss of the Week");
			case "news":
				return news(clan);
			case "drops":
				return drops(clan, rest);
			case "pb":
				return pb(clan, rest, sender);
			default:
				return null;
		}
	}

	static String help()
	{
		return new ChatMessageBuilder().append(ChatColorType.HIGHLIGHT).append("Asgardians: ").append(ChatColorType.NORMAL)
			.append("!asg groups, events, bingo, sotw, botw, news, drops [week/month/year/all], pb [boss], credit, rank, ehb, ehp, profile, eggs")
			.build();
	}

	static String groups(Clan clan)
	{
		ClanData.GroupList list = clan.getGroups();
		if (list == null)
		{
			return null;
		}
		List<ClanData.Group> open = new ArrayList<>();
		for (ClanData.Group g : ClanView.orEmpty(list.getGroups()))
		{
			if (g != null && g.getId() != null)
			{
				open.add(g);
			}
		}
		ChatMessageBuilder b = start("Open groups (" + open.size() + ")");
		if (open.isEmpty())
		{
			return b.append("none right now. Start one in the Asgardians panel.").build();
		}
		for (int i = 0; i < Math.min(open.size(), 4); i++)
		{
			ClanData.Group g = open.get(i);
			b.append(i > 0 ? " · " : "").append(ChatColorType.HIGHLIGHT)
				.append(Groups.shortTitle(g, GroupTabs.activity(g, clan.getActivities())))
				.append(ChatColorType.NORMAL).append(" " + g.seats() + (g.getWorld() != null ? " W" + g.getWorld() : "")
					+ (g.getHost() != null ? " (" + g.getHost() + ")" : ""));
		}
		if (open.size() > 4)
		{
			b.append(" · +" + (open.size() - 4) + " more");
		}
		return b.build();
	}

	static String events(Clan clan)
	{
		ClanView view = clan.getView();
		if (view == null || view.getFetchedAt() == null)
		{
			return null;
		}
		List<ClanView.EventView> live = view.live();
		List<ClanView.EventView> next = view.upcoming();
		ChatMessageBuilder b = start("Events");
		if (live.isEmpty() && next.isEmpty())
		{
			return b.append("nothing on right now.").build();
		}
		boolean first = true;
		if (!live.isEmpty())
		{
			b.append("Live: ");
			for (int i = 0; i < Math.min(live.size(), 2); i++)
			{
				ClanData.Event e = live.get(i).getEvent();
				b.append(i > 0 ? ", " : "").append(ChatColorType.HIGHLIGHT).append(name(e)).append(ChatColorType.NORMAL)
					.append(e.end() != null ? " (" + ClanView.countdown(clan.getNow(), e.end()) + " left)" : "");
			}
			first = false;
		}
		if (!next.isEmpty())
		{
			b.append(first ? "Next: " : " · Next: ");
			for (int i = 0; i < Math.min(next.size(), 2); i++)
			{
				ClanData.Event e = next.get(i).getEvent();
				b.append(i > 0 ? ", " : "").append(ChatColorType.HIGHLIGHT).append(name(e)).append(ChatColorType.NORMAL)
					.append(e.start() != null ? " in " + ClanView.countdown(clan.getNow(), e.start()) : "");
			}
		}
		return b.build();
	}

	static String bingo(Clan clan)
	{
		ClanView view = clan.getView();
		if (view == null || view.getFetchedAt() == null)
		{
			return null;
		}
		for (ClanView.EventView v : view.live())
		{
			if (!"bingo".equalsIgnoreCase(v.getEvent().getType()))
			{
				continue;
			}
			ChatMessageBuilder b = start(name(v.getEvent()));
			List<ClanData.Team> teams = new ArrayList<>(ClanView.orEmpty(v.getStandings()));
			teams.removeIf(t -> t == null || t.getName() == null);
			teams.sort(java.util.Comparator.comparing((ClanData.Team t) -> t.getRank() != null ? t.getRank() : Integer.MAX_VALUE)
				.thenComparing(t -> -(t.getPoints() != null ? t.getPoints() : 0)));
			if (teams.isEmpty())
			{
				return b.append("no scores yet.").build();
			}
			for (int i = 0; i < Math.min(teams.size(), TOP); i++)
			{
				ClanData.Team t = teams.get(i);
				String label = t.getPointsLabel() != null ? t.getPointsLabel() : "pts";
				b.append(i > 0 ? " · " : "").append((i + 1) + ". ").append(ChatColorType.HIGHLIGHT).append(t.getName())
					.append(ChatColorType.NORMAL).append(t.getPoints() != null ? " " + number(t.getPoints()) + " " + label : "");
			}
			return b.build();
		}
		return start("Bingo").append("no bingo on right now.").build();
	}

	/** The current SOTW or BOTW: its live event's standings, else the leaderboard named after it. */
	static String competition(Clan clan, String type, String title)
	{
		ClanView view = clan.getView();
		for (ClanView.EventView v : view != null ? view.live() : List.<ClanView.EventView>of())
		{
			ClanData.Event e = v.getEvent();
			if (type.equalsIgnoreCase(e.getType()))
			{
				ChatMessageBuilder b = start(name(e) + (e.end() != null ? " (" + ClanView.countdown(clan.getNow(), e.end()) + " left)" : ""));
				return rows(b, e.getStandings()).build();
			}
		}
		for (ClanData.Leaderboard board : boards(clan, "week"))
		{
			if (board.getTitle() != null && (board.getTitle().toLowerCase(Locale.UK).startsWith(type)
				|| board.getTitle().toLowerCase(Locale.UK).startsWith(title.toLowerCase(Locale.UK))))
			{
				ChatMessageBuilder b = start(board.getTitle() + (board.ends() != null ? " (" + ClanView.countdown(clan.getNow(), board.ends()) + " left)" : ""));
				return rows(b, board.getRows()).build();
			}
		}
		if (view == null || view.getFetchedAt() == null)
		{
			return null;
		}
		return start(title).append("none running right now.").build();
	}

	static String news(Clan clan)
	{
		ClanView view = clan.getView();
		if (view == null || view.getFetchedAt() == null)
		{
			return null;
		}
		List<ClanData.Announcement> news = ClanView.orEmpty(view.getAnnouncements());
		if (news.isEmpty() || news.get(0) == null || news.get(0).getTitle() == null)
		{
			return start("News").append("nothing new.").build();
		}
		ClanData.Announcement a = news.get(0);
		String ago = ClanView.ago(a.posted(), clan.getNow());
		return start("Latest news").append(ChatColorType.HIGHLIGHT).append(a.getTitle()).append(ChatColorType.NORMAL)
			.append(ago.isEmpty() ? "" : " (" + ago + ")").build();
	}

	/** The top of the Drops board for a period: this month unless week, year or all is asked for. */
	static String drops(Clan clan, String rest)
	{
		String period = period(rest);
		for (ClanData.Leaderboard board : boards(clan, period))
		{
			if (board.getTitle() != null && board.getTitle().toLowerCase(Locale.UK).startsWith("drop"))
			{
				return rows(start("Drops " + periodLabel(period)), board.getRows()).build();
			}
		}
		return null;
	}

	/**
	 * The clan's best time for a boss at each team size, and the sender's own best. "!asg pb tob", "!asg pb tob 4",
	 * "!asg pb vorkath".
	 */
	static String pb(Clan clan, String rest, String sender)
	{
		ClanData.StatsFeed stats = clan.getStats();
		if (stats == null || stats.getRecords() == null || rest.isEmpty())
		{
			return rest.isEmpty() ? start("PBs").append("try !asg pb [boss], e.g. !asg pb tob").build() : null;
		}
		String size = null;
		String bossText = rest;
		java.util.regex.Matcher m = java.util.regex.Pattern.compile("^(.*?)\\s+(solo|\\d+(?:-\\d+)?)(?:\\s*-?man)?$", java.util.regex.Pattern.CASE_INSENSITIVE).matcher(rest);
		if (m.matches())
		{
			bossText = m.group(1);
			size = m.group(2).equalsIgnoreCase("solo") ? "1" : m.group(2);
		}
		String boss = boss(bossText, stats.getRecords());
		if (boss == null)
		{
			return start("PBs").append("no clan PBs for \"" + rest + "\".").build();
		}
		ChatMessageBuilder b = start(boss + " PBs");
		int shown = 0;
		String mine = null;
		for (ClanData.PbRecord r : stats.getRecords())
		{
			if (r == null || !boss.equals(r.getBoss()) || (size != null && !size.equals(r.getTeamSize())))
			{
				continue;
			}
			List<ClanData.StatEntry> entries = ClanView.orEmpty(r.getEntries());
			if (!entries.isEmpty() && entries.get(0).getSeconds() != null && shown < 4)
			{
				ClanData.StatEntry best = entries.get(0);
				b.append(shown > 0 ? " · " : "").append(team(r.getTeamSize()) + " ").append(ChatColorType.HIGHLIGHT)
					.append(StatsTabs.time(best.getSeconds())).append(ChatColorType.NORMAL).append(" " + best.getRsn());
				shown++;
			}
			for (int i = 0; i < entries.size(); i++)
			{
				ClanData.StatEntry e = entries.get(i);
				if (mine == null && e.getSeconds() != null && DropRecorder.sameRsn(e.getRsn(), sender))
				{
					mine = sender + ": " + StatsTabs.time(e.getSeconds()) + " (" + team(r.getTeamSize()) + ", #" + (i + 1) + ")";
				}
			}
		}
		if (shown == 0)
		{
			return b.append("none yet" + (size != null ? " for " + team(size) : "") + ".").build();
		}
		if (mine != null)
		{
			b.append(" | " + mine);
		}
		return b.build();
	}

	/**
	 * The answer to a command about the player who typed it, from their clan profile; null when there's nothing to say.
	 */
	static String personal(String word, String sender, ClanData.Me p)
	{
		if (p == null)
		{
			return null;
		}
		switch (word)
		{
			case "credit":
			case "clancredit":
			{
				ChatMessageBuilder b = start("Clan credit");
				if (p.getSplitCredit() == null)
				{
					return b.append("none on record.").build();
				}
				b.append(ChatColorType.HIGHLIGHT).append(ProfileText.amount(p.getSplitCredit())).append(ChatColorType.NORMAL);
				ClanData.ProfileRank place = ranking(p, "credit");
				return b.append(place != null && place.getRank() != null ? " (#" + place.getRank() + " in the clan)" : "").build();
			}
			case "rank":
				return start("Rank").append(ChatColorType.HIGHLIGHT).append(ProfileText.rank(p.getRank())).append(ChatColorType.NORMAL)
					.append(p.getDaysInClan() != null ? " · in the clan " + ProfileText.time(p.getDaysInClan()) : "").build();
			case "ehb":
				return hours("EHB", p.getEhb(), ranking(p, "ehb"));
			case "ehp":
				return hours("EHP", p.getEhp(), ranking(p, "ehp"));
			case "eggs":
				if (p.getEggsThrown() == null && p.getEggsReceived() == null)
				{
					return start("Handeggs").append("none on record.").build();
				}
				return start("Handeggs").append(ChatColorType.HIGHLIGHT)
					.append((p.getEggsThrown() != null ? p.getEggsThrown() : 0) + " thrown").append(ChatColorType.NORMAL)
					.append(" · hit " + (p.getEggsReceived() != null ? p.getEggsReceived() : 0) + " times").build();
			case "profile":
			{
				List<String> parts = new ArrayList<>();
				parts.add(ProfileText.rank(p.getRank()));
				if (p.getDaysInClan() != null)
				{
					parts.add(ProfileText.time(p.getDaysInClan()));
				}
				if (p.getSplitCredit() != null)
				{
					parts.add("Credit " + ProfileText.amount(p.getSplitCredit()));
				}
				if (p.getEhb() != null)
				{
					parts.add("EHB " + number(p.getEhb()));
				}
				if (p.getEhp() != null)
				{
					parts.add("EHP " + number(p.getEhp()));
				}
				if (p.getClogObtained() != null)
				{
					parts.add("Log " + p.getClogObtained() + (p.getClogTotal() != null ? "/" + p.getClogTotal() : ""));
				}
				return start("Profile").append(ChatColorType.HIGHLIGHT).append(String.join(" · ", parts)).build();
			}
			default:
				return null;
		}
	}

	private static String hours(String label, Double value, ClanData.ProfileRank place)
	{
		ChatMessageBuilder b = start(label);
		if (value == null)
		{
			return b.append("not on record.").build();
		}
		return b.append(ChatColorType.HIGHLIGHT).append(number(value)).append(ChatColorType.NORMAL)
			.append(place != null && place.getRank() != null ? " (#" + place.getRank() + " in the clan)" : "").build();
	}

	/** The profile's place on a board whose name contains the word, e.g. "Clan credit" for "credit". */
	private static ClanData.ProfileRank ranking(ClanData.Me p, String word)
	{
		for (ClanData.ProfileRank r : ClanView.orEmpty(p.getRankings()))
		{
			if (r != null && r.getBoard() != null && r.getBoard().toLowerCase(Locale.UK).contains(word))
			{
				return r;
			}
		}
		return null;
	}

	/**
	 * The boss a member means: a full name, its initials ("tob", "cox", "toa", "cg"), or the start of a name. Only
	 * bosses the clan has PBs for count.
	 */
	static String boss(String text, List<ClanData.PbRecord> records)
	{
		String want = text.trim().toLowerCase(Locale.UK).replace("'", "");
		List<String> names = new ArrayList<>();
		for (ClanData.PbRecord r : ClanView.orEmpty(records))
		{
			if (r != null && r.getBoss() != null && !names.contains(r.getBoss()))
			{
				names.add(r.getBoss());
			}
		}
		for (String n : names)
		{
			if (n.toLowerCase(Locale.UK).replace("'", "").equals(want))
			{
				return n;
			}
		}
		for (String n : names)
		{
			if (initials(n).equals(want))
			{
				return n;
			}
		}
		String alias = ALIASES.get(want);
		for (String n : names)
		{
			if (alias != null && n.toLowerCase(Locale.UK).contains(alias))
			{
				return n;
			}
		}
		for (String n : names)
		{
			if (want.length() >= 3 && n.toLowerCase(Locale.UK).replace("'", "").startsWith(want))
			{
				return n;
			}
		}
		for (String n : names)
		{
			if (want.length() >= 4 && n.toLowerCase(Locale.UK).replace("'", "").contains(want))
			{
				return n;
			}
		}
		return null;
	}

	/** "Theatre of Blood" becomes "tob", "The Corrupted Gauntlet" "cg", "Chambers of Xeric: Challenge Mode" "coxcm". */
	private static String initials(String name)
	{
		StringBuilder out = new StringBuilder();
		for (String w : name.toLowerCase(Locale.UK).replace(":", " ").split("[\\s-]+"))
		{
			if (!w.isEmpty() && !w.equals("the"))
			{
				out.append(w.charAt(0));
			}
		}
		return out.toString();
	}

	/** Usual short names that aren't a boss's initials, to a word in its name. */
	private static final Map<String, String> ALIASES = Map.of(
		"cm", "challenge mode",
		"colo", "colosseum",
		"zuk", "inferno",
		"jad", "fight caves",
		"nm", "nightmare",
		"hmt", "hard mode",
		"sire", "abyssal sire",
		"hydra", "hydra",
		"muspah", "muspah",
		"gauntlet", "gauntlet");

	private static String period(String rest)
	{
		String p = rest.trim().toLowerCase(Locale.UK);
		if (p.equals("alltime") || p.equals("all-time") || p.equals("all time"))
		{
			return "all";
		}
		return PERIODS.contains(p) ? p : "month";
	}

	private static String periodLabel(String period)
	{
		switch (period)
		{
			case "week":
				return "this week";
			case "year":
				return "this year";
			case "all":
				return "all time";
			default:
				return "this month";
		}
	}

	private static List<ClanData.Leaderboard> boards(Clan clan, String period)
	{
		Map<String, List<ClanData.Leaderboard>> boards = clan.getBoards();
		List<ClanData.Leaderboard> list = boards != null ? boards.get(period) : null;
		List<ClanData.Leaderboard> out = new ArrayList<>();
		for (ClanData.Leaderboard b : ClanView.orEmpty(list))
		{
			if (b != null)
			{
				out.add(b);
			}
		}
		return out;
	}

	private static ChatMessageBuilder rows(ChatMessageBuilder b, List<ClanData.LeaderboardRow> rows)
	{
		List<ClanData.LeaderboardRow> list = ClanView.orEmpty(rows);
		if (list.isEmpty())
		{
			return b.append("no entries yet.");
		}
		for (int i = 0; i < Math.min(list.size(), TOP); i++)
		{
			ClanData.LeaderboardRow r = list.get(i);
			b.append(i > 0 ? " · " : "").append((r.getRank() != null ? r.getRank() : i + 1) + ". ").append(ChatColorType.HIGHLIGHT)
				.append(r.getRsn() != null ? r.getRsn() : "?").append(ChatColorType.NORMAL)
				.append(r.getValue() != null ? " " + r.getValue() : "");
		}
		return b;
	}

	private static ChatMessageBuilder start(String title)
	{
		return new ChatMessageBuilder().append(ChatColorType.HIGHLIGHT).append(title + ": ").append(ChatColorType.NORMAL);
	}

	private static String name(ClanData.Event e)
	{
		return e.getName() != null ? e.getName() : "Event";
	}

	private static String team(String size)
	{
		return size == null ? "" : "1".equals(size) ? "Solo" : size + "-man";
	}

	private static String number(double value)
	{
		return value == Math.rint(value) ? QuantityFormatter.formatNumber((long) value) : String.format(Locale.UK, "%,.1f", value);
	}
}

package com.asgardians;

import java.awt.Color;
import java.awt.image.BufferedImage;

/**
 * The sidebar icon: "ASG" in orange pixel letters inside an orange border, on the panel's dark brown. Drawn pixel by
 * pixel at 16 by 16 so it stays sharp, and scaled up in whole pixels for larger sizes.
 */
final class AsgIcon
{
	private static final Color BACKGROUND = PanelParts.BACKGROUND;
	private static final Color ORANGE = PanelParts.HIGHLIGHT;
	private static final int SIZE = 16;
	private static final String[] A = {".#.", "#.#", "#.#", "###", "#.#", "#.#"};
	private static final String[] S = {".##", "#..", ".#.", "..#", "..#", "##."};
	private static final String[] G = {".##", "#..", "#..", "#.#", "#.#", ".##"};

	private AsgIcon()
	{
	}

	/** The icon at {@code size} pixels: 16, or a whole multiple of 16 for a bigger one. */
	static BufferedImage create(int size)
	{
		int scale = Math.max(1, size / SIZE);
		BufferedImage img = new BufferedImage(SIZE * scale, SIZE * scale, BufferedImage.TYPE_INT_ARGB);
		boolean[][] on = pixels();
		int bg = BACKGROUND.getRGB(), fg = ORANGE.getRGB();
		for (int y = 0; y < SIZE; y++)
		{
			for (int x = 0; x < SIZE; x++)
			{
				boolean corner = (x == 0 || x == SIZE - 1) && (y == 0 || y == SIZE - 1);
				if (corner)
				{
					continue;
				}
				int colour = on[y][x] ? fg : bg;
				for (int dy = 0; dy < scale; dy++)
				{
					for (int dx = 0; dx < scale; dx++)
					{
						img.setRGB(x * scale + dx, y * scale + dy, colour);
					}
				}
			}
		}
		return img;
	}

	/** Which pixels are orange: the border, and the three letters in the middle. */
	static boolean[][] pixels()
	{
		boolean[][] on = new boolean[SIZE][SIZE];
		for (int i = 0; i < SIZE; i++)
		{
			on[0][i] = on[SIZE - 1][i] = on[i][0] = on[i][SIZE - 1] = true;
		}
		String[][] letters = {A, S, G};
		int[] xs = {2, 6, 11};
		for (int l = 0; l < letters.length; l++)
		{
			for (int r = 0; r < letters[l].length; r++)
			{
				for (int c = 0; c < 3; c++)
				{
					if (letters[l][r].charAt(c) == '#')
					{
						on[5 + r][xs[l] + c] = true;
					}
				}
			}
		}
		return on;
	}
}

