		}
	}

	static Color typeColour(ClanData.Event event)
	{
		switch (ClanView.group(event))
		{
			case "bingo":
				return BINGO_COLOUR;
			case "botw":
				return BOTW_COLOUR;
			case "sotw":
				return SOTW_COLOUR;
			default:
				return QUIET;
