	private static String teamLabel(ClanData.Team team, Map<String, String> tags)
	{
		String tag = tags.get(team.getId());
		String name = team.getName() != null ? team.getName() : "Team";
		return tag == null || name.endsWith(tag) ? name : tag + " · " + name;
