	/** The Leaderboard page; {@code kc} is the Boss kills pick and {@code skill} the XP board's skill (null for all). */
	static void leaderboards(JPanel column, Input in, Runnable refresh, Ui ui, UiActions uiActions, String[] kc, String skill)
	{
		column.removeAll();
		if (in.getNotConnected() != null)
		{
			Card card = new Card("Leaderboards");
			card.add(small(in.getNotConnected(), QUIET));
			addCard(column, card);
			return;
		}
		int selected = PERIODS.indexOf(period(ui.getPeriod()));
		List<ClanData.Leaderboard> boards = new ArrayList<>();
		for (ClanData.Leaderboard b : in.getLeaderboards().getOrDefault(PERIODS.get(selected), List.of()))
		{
			if (b != null)
			{
				boards.add(b);
			}
		}
		List<String> titles = new ArrayList<>();
		for (ClanData.Leaderboard b : boards)
		{
			titles.add(b.getTitle() != null ? b.getTitle() : "Board");
		}
		int pickedBoard = Math.max(0, titles.indexOf(ui.getBoard()));
		javax.swing.JComponent boardBox = titles.isEmpty() ? PanelParts.dropdown(List.of("No boards"), 0, i -> { })
			: PanelParts.dropdown(titles, pickedBoard, i -> uiActions.board(titles.get(i)));
		addCard(column, PanelParts.dropdowns(boardBox,
			PanelParts.dropdown(PERIOD_LABELS, selected, i -> uiActions.period(PERIODS.get(i)))));
		if (boards.isEmpty())
		{
			if (in.getView().getFetchedAt() != null)
			{
				Card card = new Card("Leaderboards");
				card.add(small("No leaderboards to show for " + PERIOD_LABELS.get(selected).toLowerCase(java.util.Locale.UK) + " right now.", QUIET));
				addCard(column, card);
			}
		}
		else if (boards.get(pickedBoard).getSkills() != null && !boards.get(pickedBoard).getSkills().isEmpty())
		{
			skillXp(column, boards.get(pickedBoard), in, skill, uiActions);
		}
		else if (boards.get(pickedBoard).getBosses() != null && !boards.get(pickedBoard).getBosses().isEmpty())
		{
			bossKills(column, boards.get(pickedBoard), in, kc, uiActions);
		}
		else
		{
			board(column, boards.get(pickedBoard), in);
		}
		addCard(column, footer(in.getView(), in, refresh));
	}

	/** XP: "All skills" shows total XP; picking a skill shows that skill's own board, in the game's skill order. */
	private static void skillXp(JPanel column, ClanData.Leaderboard all, Input in, String skill, UiActions uiActions)
	{
		java.util.Map<String, ClanData.SkillBoard> bySkill = new java.util.LinkedHashMap<>();
		for (ClanData.SkillBoard b : all.getSkills())
		{
			if (b != null && b.getSkill() != null)
			{
				bySkill.put(b.getSkill(), b);
			}
		}
		List<String> names = new ArrayList<>(bySkill.keySet());
		names.sort(java.util.Comparator.comparingInt(ClanTabs::skillOrder).thenComparing(String.CASE_INSENSITIVE_ORDER));
		List<String> labels = new ArrayList<>();
		labels.add("All skills");
		labels.addAll(names);
		String picked = skill != null && bySkill.containsKey(skill) ? skill : null;
		column.add(Box.createVerticalStrut(6));
		addLeft(column, PanelParts.dropdowns(PanelParts.dropdown(labels, picked == null ? 0 : labels.indexOf(picked),
			i -> uiActions.xpPick(i == 0 ? null : labels.get(i))), null));
		if (picked == null)
		{
			board(column, all, in);
			return;
		}
		ClanData.SkillBoard board = bySkill.get(picked);
		if (board.getTitle() == null)
		{
			board.setTitle(picked + " XP");
		}
		board(column, board, in);
	}

	/** Where a skill sits in the game's skill list; unknown names go last. */
	static int skillOrder(String name)
	{
		for (net.runelite.api.Skill s : net.runelite.api.Skill.values())
		{
			if (s.getName().equalsIgnoreCase(name))
			{
				return s.ordinal();
			}
		}
		return Integer.MAX_VALUE;
	}

	/**
	 * Boss kills, like the PBs page: "All bosses" shows total kills; picking a category (Raids, Bosses, Skilling,
	 * Minigames), a group and a boss shows that boss's own board.
	 */
	private static void bossKills(JPanel column, ClanData.Leaderboard all, Input in, String[] kc, UiActions uiActions)
	{
		java.util.Map<String, java.util.Map<String, java.util.Map<String, ClanData.BossBoard>>> tree = new java.util.LinkedHashMap<>();
		for (ClanData.BossBoard b : all.getBosses())
		{
			if (b == null || b.getBoss() == null)
			{
				continue;
			}
			String[] where = BossGroups.place(b.getBoss(), b.getCategory(), b.getGroup());
			tree.computeIfAbsent(where[0], c -> new java.util.LinkedHashMap<>())
				.computeIfAbsent(where[1] != null ? where[1] : "", g -> new java.util.TreeMap<>(String.CASE_INSENSITIVE_ORDER))
				.put(b.getBoss(), b);
		}
		for (java.util.Map<String, java.util.Map<String, ClanData.BossBoard>> groups : tree.values())
		{
			if (groups.size() > 1 && groups.containsKey(""))
			{
				java.util.Map<String, ClanData.BossBoard> loose = groups.remove("");
				groups.computeIfAbsent(BossGroups.OTHER, g -> new java.util.TreeMap<>(String.CASE_INSENSITIVE_ORDER)).putAll(loose);
			}
		}
		List<String> cats = new ArrayList<>(tree.keySet());
		List<String> seen = new ArrayList<>(cats);
		cats.sort(java.util.Comparator.comparingInt((String c) -> BossGroups.categoryOrder(c)).thenComparingInt(seen::indexOf));
		List<String> catLabels = new ArrayList<>();
		catLabels.add("All bosses");
		catLabels.addAll(cats);
		String cat = kc[0] != null && cats.contains(kc[0]) ? kc[0] : null;
		javax.swing.JComponent catBox = PanelParts.dropdown(catLabels, cat == null ? 0 : catLabels.indexOf(cat),
			i -> uiActions.kcPick(i == 0 ? null : catLabels.get(i), null, null));
		if (cat == null)
		{
			column.add(Box.createVerticalStrut(6));
			addLeft(column, PanelParts.dropdowns(catBox, null));
			board(column, all, in);
			return;
		}
		java.util.Map<String, java.util.Map<String, ClanData.BossBoard>> groups = tree.get(cat);
		List<String> groupNames = new ArrayList<>(groups.keySet());
		List<String> groupSeen = new ArrayList<>(groupNames);
		groupNames.sort(java.util.Comparator.comparingInt((String g) -> BossGroups.groupOrder(g)).thenComparingInt(groupSeen::indexOf));
		String group = kc[1] != null && groupNames.contains(kc[1]) ? kc[1] : groupNames.get(0);
		String groupPick = group.isEmpty() ? null : group;
		javax.swing.JComponent groupBox = !group.isEmpty()
			? PanelParts.dropdown(groupNames, groupNames.indexOf(group), i -> uiActions.kcPick(cat, groupNames.get(i), null)) : null;
		column.add(Box.createVerticalStrut(6));
		addLeft(column, PanelParts.dropdowns(catBox, groupBox));
		java.util.Map<String, ClanData.BossBoard> bosses = groups.get(group);
		List<String> bossNames = new ArrayList<>(bosses.keySet());
		String boss = kc[2] != null && bossNames.contains(kc[2]) ? kc[2] : bossNames.get(0);
		column.add(Box.createVerticalStrut(6));
		addLeft(column, PanelParts.dropdowns(PanelParts.dropdown(bossNames, bossNames.indexOf(boss),
			i -> uiActions.kcPick(cat, groupPick, bossNames.get(i))), null));
		ClanData.BossBoard picked = bosses.get(boss);
		if (picked.getTitle() == null)
		{
			picked.setTitle(boss + " kills");
		}
		board(column, picked, in);
	}

	/** One board: a podium for the top three, then the rest, with the member's own row standing out. */
	private static void board(JPanel column, ClanData.Leaderboard board, Input in)
	{
		if (board.getSubtitle() != null || board.ends() != null)
		{
			column.add(Box.createVerticalStrut(4));
			String sub = board.getSubtitle() != null ? board.getSubtitle() : "";
			if (board.ends() != null)
			{
				sub += (sub.isEmpty() ? "" : " · ") + "Ends in " + ClanView.countdown(in.getNow(), board.ends());
			}
			addLeft(column, small(sub, QUIET));
		}
		List<ClanData.LeaderboardRow> rows = new ArrayList<>();
		for (ClanData.LeaderboardRow r : ClanView.orEmpty(board.getRows()))
		{
			if (r != null)
			{
				rows.add(r);
			}
		}
		String myName = board.getMe() != null ? board.getMe().getRsn() : null;
		if (rows.isEmpty())
		{
			Card card = new Card(null);
			card.add(small("No entries yet.", QUIET));
			addCard(column, card);
			return;
		}
		// First place in gold, as on the PBs page; then the rest, silver and bronze for second and third.
		ClanData.LeaderboardRow first = rows.get(0);
		boolean firstMine = DropRecorder.sameRsn(first.getRsn(), myName);
		column.add(Box.createVerticalStrut(PanelParts.GAP));
		javax.swing.JLabel picture = board instanceof ClanData.BossBoard
			? PanelParts.bossBox(((ClanData.BossBoard) board).getBoss(), 38)
			: board instanceof ClanData.SkillBoard
			? PanelParts.skillBox(((ClanData.SkillBoard) board).getSkill(), 38)
			: PanelParts.placeBox(first.getRank() != null ? first.getRank() : 1, 38);
		addLeft(column, PanelParts.firstPlace(picture,
			(board.getTitle() != null ? board.getTitle() : "Leaderboard").toUpperCase(Locale.UK),
			first.getValue() != null ? first.getValue() : "",
			(first.getRsn() != null ? first.getRsn() : "?") + (firstMine ? "  (you)" : "")));
		if (rows.size() > 1)
		{
			column.add(Box.createVerticalStrut(PanelParts.GAP));
			addLeft(column, PanelParts.section("Top " + rows.size()));
		}
		for (ClanData.LeaderboardRow row : rows.subList(1, rows.size()))
		{
			column.add(Box.createVerticalStrut(4));
			addLeft(column, rankCard(row, DropRecorder.sameRsn(row.getRsn(), myName)));
		}
		ClanData.LeaderboardRow mine = board.rowBelowTop();
		if (mine != null)
		{
			column.add(Box.createVerticalStrut(8));
			addLeft(column, rankCard(mine, true));
		}
	}

	private static Card rankCard(ClanData.LeaderboardRow row, boolean mine)
	{
		return PanelParts.placeCard(row.getRank(), row.getRsn(), row.getValue(), TEXT, mine);
	}

	static void news(JPanel column, Input in, Runnable refresh)
	{
		news(column, in, refresh, java.util.Set.of(), id -> { });
	}

	/**
	 * The News page: each announcement as a short summary card (title, when and who, and a line of its text). Clicking a
	 * card opens it to the full text and its "Read more" link; clicking again closes it.
	 */
	static void news(JPanel column, Input in, Runnable refresh, java.util.Set<Long> open, java.util.function.LongConsumer toggle)
	{
		column.removeAll();
		if (in.getNotConnected() != null)
		{
			Card card = new Card("News");
			card.add(small(in.getNotConnected(), QUIET));
			addCard(column, card);
			return;
		}
		List<ClanData.Announcement> items = new ArrayList<>(in.getView().getAnnouncements());
		items.sort((a, b) -> Long.compare(b.getId(), a.getId()));
		for (ClanData.Announcement a : items)
		{
			boolean fresh = a.getId() > in.getLastReadAnnouncementId();
			boolean expanded = open.contains(a.getId());
			Card card = new Card(null);
			card.setBorder(new javax.swing.border.EmptyBorder(6, 8, 6, 8));
			if (fresh)
			{
				card.outlined(HIGHLIGHT, PanelParts.CARD);
			}
			else if (expanded)
			{
				card.outlined(PanelParts.LINE, PanelParts.CARD_HOVER);
			}
			JPanel top = new JPanel(new java.awt.BorderLayout(5, 0));
			top.setOpaque(false);
			top.add(PanelParts.dotIcon(fresh ? HIGHLIGHT : PanelParts.LINE), java.awt.BorderLayout.WEST);
			top.add(PanelParts.bold(a.getTitle() != null ? a.getTitle() : "Announcement", TEXT), java.awt.BorderLayout.CENTER);
			top.add(PanelParts.plain(expanded ? "–" : "+", QUIET), java.awt.BorderLayout.EAST);
			card.addWide(top);
			String by = a.getPostedBy() != null ? " · " + a.getPostedBy() : "";
			JLabel when = PanelParts.cut((fresh ? "New · " : "") + ClanView.ago(a.posted(), in.getNow()) + by, fresh ? HIGHLIGHT : QUIET);
			when.setBorder(new javax.swing.border.EmptyBorder(0, 11, 0, 0));
			card.addWide(when);
			String body = a.getBody() != null ? a.getBody().trim() : "";
			if (expanded)
			{
				card.gap();
				card.add(small(body, TEXT));
				javax.swing.JLabel more = websiteLink("Read more ›", a.getUrl(), in);
				if (more != null)
				{
					card.gap();
					card.addWide(PanelParts.spread(null, more));
				}
			}
			else if (!body.isEmpty())
			{
				JLabel preview = PanelParts.cut(preview(body), QUIET);
				preview.setBorder(new javax.swing.border.EmptyBorder(2, 11, 0, 0));
				card.addWide(preview);
			}
			long id = a.getId();
			card.onClick(() -> toggle.accept(id), expanded ? "Close" : "Read it");
			addCard(column, card);
		}
		if (in.getView().getFetchedAt() != null && items.isEmpty())
		{
			Card card = new Card("News");
			card.add(small("No announcements yet.", QUIET));
			addCard(column, card);
		}
		addCard(column, footer(in.getView(), in, refresh));
	}

	/** The first line of an announcement, for its summary card. */
	static String preview(String body)
	{
		String line = body.split("\\R", 2)[0].trim();
		return line.length() > 80 ? line.substring(0, 79) + "…" : line;
	}
	/** "Live, ends in 1d 7h (Tue 3 Nov 00:00)" or "Starts in 4d 7h (Fri 6 Nov 00:00)". */
	private static String when(ClanData.Event event, Input in)
	{
		return event.isLive()
			? "Live, ends in " + ClanView.countdown(in.getNow(), event.end()) + " (" + ClanView.localTime(event.end(), in.getZone()) + ")"
			: "Starts in " + ClanView.countdown(in.getNow(), event.start()) + " (" + ClanView.localTime(event.start(), in.getZone()) + ")";
	}
	/** Sign-up state, the member's own status, Sign up / Withdraw, and the list of who's signed up. */
	private static void signups(Card card, ClanData.Event event, Input in, Actions actions)
	{
		ClanData.Signup s = event.getSignup();
		if (s == null)
		{
			return;
		}
		card.gap();
		boolean full = s.getCap() != null && s.getCount() != null && s.getCount() >= s.getCap();
		String state = !s.isOpen() ? "Sign-ups closed"
			: s.closes() != null ? "Sign-ups close in " + ClanView.countdown(in.getNow(), s.closes()) : "Sign-ups open";
		card.add(PanelParts.status(s.isOpen() ? GOOD : QUIET, state));
		if (s.getCount() != null)
		{
			card.add(small(s.getCount() + (s.getCap() != null ? " of " + s.getCap() : "") + " signed up", QUIET));
		}
		if (s.getNote() != null)
		{
			card.add(small(s.getNote(), TEXT));
		}

		if (s.isSignedUp())
		{
			String status = "waitlist".equals(s.getMyStatus()) ? "You're on the waitlist"
				: "confirmed".equals(s.getMyStatus()) ? "You're confirmed" : "You're signed up";
			card.add(small("✔ " + status, GOOD));
			if (s.getPaid() != null)
			{
				card.add(small(s.getPaid() ? "Buy-in paid" : "Buy-in not paid yet", s.getPaid() ? GOOD : TODO));
			}
		}

		if (in.getBusy().contains(event.getId()))
		{
			card.add(small("Sending…", QUIET));
		}
		else if (s.isOpen())
		{
			card.gap();
			if (s.isSignedUp())
			{
				card.addWide(button("Withdraw", () -> actions.withdraw(event)));
			}
			else
			{
				card.addWide(button(full ? "Join the waitlist" : "Sign up", () -> actions.signUp(event)));
			}
		}

		boolean open = in.getExpanded().contains(event.getId());
		String count = s.getCount() != null ? " (" + s.getCount() + ")" : "";
		card.gap();
		card.addWide(PanelParts.spread(
			PanelParts.link((open ? "Hide sign-ups" : "See who's signed up") + count, () -> actions.toggleSignups(event)),
			websiteLink("Website", event.getUrl(), in)));
		if (open)
		{
			ClanData.SignupList list = in.getSignupLists().get(event.getId());
			if (list == null)
			{
				card.add(small("Loading…", QUIET));
			}
			else if (ClanView.orEmpty(list.getSignups()).isEmpty())
			{
				card.add(small("Nobody yet.", QUIET));
			}
			else
			{
				for (ClanData.SignupEntry entry : list.getSignups())
				{
					Color dot = entry.getPaid() == null ? QUIET : entry.getPaid() ? GOOD : TODO;
					String name = entry.getRsn() + (entry.getTeam() != null ? " · " + entry.getTeam() : "");
					String tip = entry.getPaid() == null ? null : entry.getPaid() ? "Buy-in paid" : "Buy-in not paid yet";
					card.addWide(dotRow(dot, name, statusLabel(entry.getStatus()), tip));
				}
			}
		}
	}

	private static String statusLabel(String status)
	{
		if ("waitlist".equals(status))
		{
			return "waitlist";
		}
		return "confirmed".equals(status) ? "confirmed" : "";
	}

	/** One quiet line under the cards: when it was last loaded and a Refresh link, plus any problem loading. */
	private static JPanel footer(ClanView view, Input in, Runnable refresh)
	{
		JPanel footer = PanelParts.column();
		if (view.getError() != null)
		{
			footer.add(small(view.getError(), BAD));
		}
		String updated = view.getFetchedAt() != null
			? "Updated " + ClanView.clock(view.getFetchedAt(), in.getZone())
			: "Loading…";
		JPanel row = PanelParts.spread(PanelParts.plain(updated, QUIET), PanelParts.link("Refresh", refresh));
		row.setAlignmentX(LEFT);
		row.setMaximumSize(new java.awt.Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		footer.add(row);
		return footer;
	}

	private static String standing(ClanData.Team team)
	{
		StringBuilder out = new StringBuilder();
		if (team.getRank() != null)
		{
			out.append("Rank #").append(team.getRank());
		}
		String points = points(team);
		if (points != null)
		{
			out.append(out.length() > 0 ? " · " : "").append(points);
		}
		return out.toString();
	}

	private static String points(ClanData.Team team)
	{
		if (team.getPoints() == null)
		{
			return null;
		}
		String value = team.getPoints() >= 100_000
			? QuantityFormatter.quantityToStackSize(Math.round(team.getPoints()))
			: trim(team.getPoints());
		return value + (team.getPointsLabel() != null ? " " + team.getPointsLabel() : "");
	}

	private static String trim(double value)
	{
		return value == Math.floor(value) ? String.valueOf((long) value) : String.valueOf(value);
	}
	private static String stateLabel(ClanData.Tile tile)
	{
		if (tile.isComplete())
		{
			return "completed";
		}
		if ("pending".equals(tile.getState()))
		{
			return "submitted, waiting for review";
		}
		return tile.getState() != null ? tile.getState() : "needed";
	}

	private static Color colour(String hex, Color fallback)
	{
		try
		{
			return hex != null ? Color.decode(hex) : fallback;
		}
		catch (NumberFormatException e)
		{
			return fallback;
		}
	}
}

package com.asgardians;

import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import lombok.Value;

/**
 * Everything the Events and News tabs show, plus the logic that decides which chat notifications to send. Built from
 * the latest fetch; the plugin swaps in a new one each time. Pure, so it can be tested.
 */
@Value
class ClanView
{
	/** How many unread titles to list in chat at login. */
	private static final int LOGIN_NEWS_TITLES = 3;

	/** An event with whatever was fetched for it. */
	@Value
	static class EventView
	{
		ClanData.Event event;
		/** The member's own team, with its members. */
		ClanData.Team team;
		List<ClanData.Team> standings;
		/** The member's own team's board. */
		ClanData.Board board;
		/** Every team's board by team ID, when the website sends them all. */
		Map<String, ClanData.Board> teamBoards;
		/** The event's recent drops, newest first. Null when the website doesn't send them. */
		List<ClanData.Drop> drops;

		EventView(ClanData.Event event, ClanData.Team team, List<ClanData.Team> standings, ClanData.Board board)
		{
			this(event, team, standings, board, Map.of());
		}

		EventView(ClanData.Event event, ClanData.Team team, List<ClanData.Team> standings, ClanData.Board board,
			Map<String, ClanData.Board> teamBoards)
		{
			this(event, team, standings, board, teamBoards, null);
		}

		EventView(ClanData.Event event, ClanData.Team team, List<ClanData.Team> standings, ClanData.Board board,
			Map<String, ClanData.Board> teamBoards, List<ClanData.Drop> drops)
		{
			this.event = event;
			this.team = team;
			this.standings = standings;
			this.board = board;
			this.teamBoards = teamBoards;
			this.drops = drops;
		}

		/** Drops this member must pick a tile for. */
		List<ClanData.Drop> choices()
		{
			List<ClanData.Drop> out = new ArrayList<>();
			for (ClanData.Drop drop : orEmpty(drops))
			{
				if (drop.getId() != null && drop.needsChoice())
				{
					out.add(drop);
				}
			}
			return out;
		}

		/**
		 * Every team, in a fixed order (by ID, so badges don't swap when the standings change). The member's own team
		 * comes from /team, which always has its members.
		 */
		List<ClanData.Team> teams()
		{
			List<ClanData.Team> out = new ArrayList<>();
			boolean ownListed = false;
			for (ClanData.Team t : standings)
			{
				if (team != null && t.getId() != null && t.getId().equals(team.getId()))
				{
					out.add(merge(t, team));
					ownListed = true;
				}
				else
				{
					out.add(t);
				}
			}
			if (team != null && !ownListed)
			{
				out.add(team);
			}
			out.sort((a, b) -> String.valueOf(a.getId()).compareTo(String.valueOf(b.getId())));
			return out;
		}

		/** The member's own team as {@link #boardTeams()} lists it, or null when they aren't on one. */
		String ownBoardTeamId()
		{
			String own = team != null && team.getId() != null ? team.getId() : event.getTeamId();
			for (ClanData.Team t : boardTeams())
			{
				if (OWN_BOARD.equals(t.getId()) || (own != null && own.equals(t.getId())))
				{
					return t.getId();
				}
			}
			return null;
		}

		/** The teams to check boards for. With no team data, the member's own board stands in as "Your team". */
		List<ClanData.Team> boardTeams()
		{
			List<ClanData.Team> teams = teams();
			if (teams.isEmpty() && board != null)
			{
				ClanData.Team own = new ClanData.Team();
				own.setId(OWN_BOARD);
				own.setName("Your team");
				return List.of(own);
			}
			return teams;
		}

		/** A team's board: from the all-teams list, or the member's own board for their own team. */
		ClanData.Board boardOf(String teamId)
		{
			if (OWN_BOARD.equals(teamId))
			{
				return board;
			}
			ClanData.Board found = teamId != null ? teamBoards.get(teamId) : null;
			if (found == null && team != null && teamId != null && teamId.equals(team.getId()))
			{
				return board;
			}
			return found;
		}

		/** Each team's badge text, by team ID. */
		Map<String, String> tags()
		{
			return ClanView.tags(teams());
		}

		private static ClanData.Team merge(ClanData.Team standing, ClanData.Team own)
		{
			ClanData.Team out = new ClanData.Team();
			out.setId(standing.getId());
			out.setName(standing.getName() != null ? standing.getName() : own.getName());
			out.setColour(standing.getColour() != null ? standing.getColour() : own.getColour());
			out.setCaptain(own.getCaptain() != null ? own.getCaptain() : standing.getCaptain());
			out.setTag(standing.getTag() != null ? standing.getTag() : own.getTag());
			out.setMembers(own.getMembers() != null ? own.getMembers() : standing.getMembers());
			out.setMemberCount(standing.getMemberCount());
			out.setPoints(standing.getPoints());
			out.setPointsLabel(standing.getPointsLabel());
			out.setRank(standing.getRank());
			return out;
		}
	}

	/** Stands for the member's own board when the website sent no team details. */
	private static final String OWN_BOARD = "";

	List<EventView> events;
	List<ClanData.Announcement> announcements;
	/** When this was fetched; null before the first fetch. */
	Instant fetchedAt;
	/** Why the last fetch failed, if it did. */
	String error;

	static ClanView empty()
	{
		return new ClanView(List.of(), List.of(), null, null);
	}

	List<EventView> live()
	{
		List<EventView> out = new ArrayList<>();
		for (EventView view : events)
		{
			if (view.getEvent().isLive())
			{
				out.add(view);
			}
		}
		return out;
	}

	List<EventView> upcoming()
	{
		List<EventView> out = new ArrayList<>();
		for (EventView view : events)
		{
			if (view.getEvent().isUpcoming())
			{
				out.add(view);
			}
		}
		out.sort((a, b) ->
		{
			Instant x = a.getEvent().start();
			Instant y = b.getEvent().start();
			return x == null || y == null ? 0 : x.compareTo(y);
		});
		return out;
	}

	long latestAnnouncementId()
	{
		long latest = 0;
		for (ClanData.Announcement a : announcements)
		{
			latest = Math.max(latest, a.getId());
		}
		return latest;
	}

	int unread(long lastReadId)
	{
		int count = 0;
		for (ClanData.Announcement a : announcements)
		{
			if (a.getId() > lastReadId)
			{
				count++;
			}
		}
		return count;
	}

	/** Live events that aren't Boss or Skill of the Week: the Events tab's Current event page. */
	List<EventView> current()
	{
		List<EventView> out = new ArrayList<>();
		for (EventView view : live())
		{
			String group = group(view.getEvent());
			if (!"botw".equals(group) && !"sotw".equals(group))
			{
				out.add(view);
			}
		}
		return out;
	}

	/** The live event whose teams get badges in clan chat: the first one the member is in, else the first with teams. */
	EventView badgeEvent()
	{
		EventView first = null;
		for (EventView view : current())
		{
			if (view.teams().isEmpty())
			{
				continue;
			}
			if (view.getEvent().isIn())
			{
				return view;
			}
			if (first == null)
			{
				first = view;
			}
		}
		return first;
	}

	/**
	 * Badge text for each team. The website's own tag wins. Otherwise teams named with numbers ("Team 1", "Team 2") get
	 * their number, and anything else gets A, B, C in a fixed order.
	 */
	static Map<String, String> tags(List<ClanData.Team> teams)
	{
		Map<String, String> out = new java.util.LinkedHashMap<>();
		Set<String> numbers = new HashSet<>();
		boolean numbered = true;
		for (ClanData.Team t : teams)
		{
			java.util.regex.Matcher m = TRAILING_NUMBER.matcher(t.getName() != null ? t.getName() : "");
			numbered &= m.find() && numbers.add(m.group(1));
		}
		int index = 0;
		for (ClanData.Team t : teams)
		{
			String tag;
			if (t.getTag() != null && !t.getTag().trim().isEmpty())
			{
				tag = t.getTag().trim();
			}
			else if (numbered)
			{
				java.util.regex.Matcher m = TRAILING_NUMBER.matcher(t.getName());
				m.find();
				tag = m.group(1);
			}
			else
			{
				tag = index < 26 ? String.valueOf((char) ('A' + index)) : String.valueOf(index + 1);
			}
			out.put(t.getId(), tag.length() > 2 ? tag.substring(0, 2) : tag);
			index++;
		}
		return out;
	}

	private static final java.util.regex.Pattern TRAILING_NUMBER = java.util.regex.Pattern.compile("(\\d{1,2})\\s*$");

	// ---- groups ----

	/** The groups the Events tab shows, in order. */
	static final List<String> GROUPS = List.of("bingo", "botw", "sotw", "other");

	static String groupLabel(String group)
	{
		switch (group)
		{
			case "bingo":
				return "Bingo events";
			case "botw":
				return "Boss of the Week";
			case "sotw":
				return "Skill of the Week";
			default:
				return "Other events";
		}
	}

	/** Which group an event belongs to. R2R, Twisted Rainbow and Tug of Zaros run as bingo events. */
	static String group(ClanData.Event event)
	{
		String kind = event.getKind() != null ? event.getKind() : "";
		String type = event.getType() != null ? event.getType() : "";
		if ("botw".equals(type) || "sotw".equals(type))
		{
			return type;
		}
		if ("bingo".equals(type) || "bingo".equals(kind) || "r2r".equals(kind) || "twisted-rainbow".equals(kind) || "toz".equals(kind))
		{
			return "bingo";
		}
		return "other";
	}

	/** One group's events: live first, then upcoming, soonest first. */
	List<EventView> inGroup(String group)
	{
		List<EventView> out = new ArrayList<>();
		for (EventView view : live())
		{
			if (group.equals(group(view.getEvent())))
			{
				out.add(view);
			}
		}
		for (EventView view : upcoming())
		{
			if (group.equals(group(view.getEvent())))
			{
				out.add(view);
			}
		}
		return out;
	}

	// ---- notifications ----

	/** Announcements newer than the last one the member was told about, oldest first. */
	List<ClanData.Announcement> newAnnouncements(long lastNotifiedId)
	{
		List<ClanData.Announcement> out = new ArrayList<>();
		for (ClanData.Announcement a : announcements)
		{
			if (a.getId() > lastNotifiedId)
			{
				out.add(a);
			}
		}
		out.sort((a, b) -> Long.compare(a.getId(), b.getId()));
		return out;
	}

	/** A chat line for each bingo-style event the member is in whose buy-in isn't marked as paid. Waitlisted members owe nothing yet. */
	List<String> buyInReminders()
	{
		List<String> lines = new ArrayList<>();
		for (EventView view : inGroup("bingo"))
		{
			ClanData.Event event = view.getEvent();
			ClanData.Signup signup = event.getSignup();
			if (signup != null && signup.isSignedUp() && !"waitlist".equals(signup.getMyStatus())
				&& Boolean.FALSE.equals(signup.getPaid()))
			{
				lines.add("Your buy-in for " + event.getName() + " isn't marked as paid."
					+ (signup.getNote() != null ? " " + signup.getNote() : ""));
			}
		}
		return lines;
	}

	/** The chat lines for unread announcements at login, newest first; empty when everything has been read. */
	List<String> loginNews(long lastReadId)
	{
		List<ClanData.Announcement> unread = newAnnouncements(lastReadId);
		Collections.reverse(unread);
		if (unread.isEmpty())
		{
			return List.of();
		}
		if (unread.size() == 1)
		{
			return List.of("Unread news: " + unread.get(0).getTitle() + ". Open the News tab to read it.");
		}
		List<String> lines = new ArrayList<>();
		lines.add("You have " + unread.size() + " unread announcements. Open the News tab to read them.");
		for (ClanData.Announcement a : unread.subList(0, Math.min(unread.size(), LOGIN_NEWS_TITLES)))
		{
			lines.add("- " + a.getTitle());
		}
		if (unread.size() > LOGIN_NEWS_TITLES)
		{
			lines.add("...and " + (unread.size() - LOGIN_NEWS_TITLES) + " more.");
		}
		return lines;
	}

	/**
	 * Chat lines for tiles that changed since the previous view, on every team's board of the events the member is in:
	 * new submissions, items accepted on tiles that need several, completed tiles and declines. Each line names the team.
	 */
	List<String> tileChanges(ClanView previous)
	{
		return tileChanges(previous, (key, rsn) -> false);
	}

	/**
	 * As {@link #tileChanges(ClanView)}, leaving out a "submitted" line when {@code announced} says the member was
	 * already told about it when the drop happened. It's given the tile's key (see {@link #tileKey}) and the RSN
	 * that sent the latest item, if known.
	 */
	List<String> tileChanges(ClanView previous, java.util.function.BiPredicate<String, String> announced)
	{
		if (previous == null)
		{
			return List.of();
		}
		Map<String, ClanData.Tile> before = new HashMap<>();
		for (EventView view : previous.getEvents())
		{
			for (ClanData.Team t : view.boardTeams())
			{
				ClanData.Board board = view.boardOf(t.getId());
				if (board != null && board.getTiles() != null)
				{
					for (ClanData.Tile tile : board.getTiles())
					{
						before.put(tileKey(view.getEvent().getId(), t.getId(), tile.getId()), tile);
					}
				}
			}
		}
		List<String> out = new ArrayList<>();
		for (EventView view : events)
		{
			if (!view.getEvent().isIn())
			{
				continue;
			}
			for (ClanData.Team t : view.boardTeams())
			{
				ClanData.Board board = view.boardOf(t.getId());
				if (board == null || board.getTiles() == null)
				{
					continue;
				}
				String team = t.getName() != null ? t.getName() : "A team";
				for (ClanData.Tile tile : board.getTiles())
				{
					String key = tileKey(view.getEvent().getId(), t.getId(), tile.getId());
					ClanData.Tile old = before.get(key);
					if (old != null)
					{
						tileChange(view.getEvent().getName(), team, old, tile, out,
							rsn -> announced.test(key, rsn));
					}
				}
			}
		}
		return out;
	}

	/** Identifies one tile on one team's board. */
	static String tileKey(String eventId, String teamId, String tileId)
	{
		return eventId + "/" + teamId + "/" + tileId;
	}

	/** What changed on one tile, as chat lines. */
	static void tileChange(String event, String team, ClanData.Tile old, ClanData.Tile now, List<String> out)
	{
		tileChange(event, team, old, now, out, rsn -> false);
	}

	private static void tileChange(String event, String team, ClanData.Tile old, ClanData.Tile now, List<String> out,
		java.util.function.Predicate<String> announced)
	{
		String tile = "\"" + now.getName() + "\"";
		boolean newSubmission = now.getPending() != null && old.getPending() != null
			? now.getPending() > old.getPending()
			: "pending".equals(now.getState()) && !"pending".equals(old.getState());
		ClanData.TileItem latest = now.getLatest();
		if (newSubmission && !now.isComplete() && !announced.test(latest != null ? latest.getRsn() : null))
		{
			String who = latest != null && latest.getRsn() != null ? latest.getRsn() + " (" + team + ")" : team;
			String what = latest != null && latest.getItem() != null ? latest.getItem() : "an item";
			String soFar = now.progress() != null
				? " " + (now.accepted() != null ? now.accepted() : 0) + " of " + now.needed() + " accepted so far." : "";
			out.add(event + ": " + who + " submitted " + what + " for " + tile + "." + soFar);
		}
		if (now.isComplete() && !old.isComplete())
		{
			out.add(event + ": " + team + " completed " + tile + ".");
		}
		else if (!now.isComplete() && now.accepted() != null && old.accepted() != null && now.accepted() > old.accepted())
		{
			out.add(event + ": " + team + " had an item accepted for " + tile
				+ (now.progress() != null ? " (" + now.progress() + ")" : "") + ".");
		}
		if ("declined".equals(now.getState()) && !"declined".equals(old.getState()))
		{
			out.add(event + ": " + team + "'s submission for " + tile + " was declined.");
		}
	}

	/** Drops, across live events, that this member must pick a tile for, as {event name, drop}. */
	List<Map.Entry<String, ClanData.Drop>> choices()
	{
		List<Map.Entry<String, ClanData.Drop>> out = new ArrayList<>();
		for (EventView view : events)
		{
			if (view.getEvent().isLive())
			{
				for (ClanData.Drop drop : view.choices())
				{
					out.add(Map.entry(view.getEvent().getName(), drop));
				}
			}
		}
		return out;
	}

	/** "just now", "5m ago", "3h ago" or "2d ago". */
	static String ago(Instant at, Instant now)
	{
		if (at == null || now == null)
		{
			return "";
		}
		long minutes = Math.max(Duration.between(at, now).toMinutes(), 0);
		if (minutes < 1)
		{
			return "just now";
		}
		if (minutes < 60)
		{
			return minutes + "m ago";
		}
		long hours = minutes / 60;
		return hours < 24 ? hours + "h ago" : hours / 24 + "d ago";
	}

	/** A dropped item that counts on the member's own board: the tiles it fits and the chat line. */
	@Value
	static class DropMatch
	{
		/** Every tile it fits, by tile key. */
		List<String> keys;
		String message;
	}

	/**
	 * Tiles on the member's own team's board, in live events they're in, that these items count towards: tiles not
	 * yet complete with an item of the same ID still short of its count. One line per tile.
	 */
	List<DropMatch> dropMatches(List<Record.Item> items)
	{
		List<DropMatch> out = new ArrayList<>();
		if (items == null || items.isEmpty())
		{
			return out;
		}
		for (EventView view : events)
		{
			if (!view.getEvent().isLive() || !view.getEvent().isIn())
			{
				continue;
			}
			String teamId = view.ownBoardTeamId();
			ClanData.Board board = teamId != null ? view.boardOf(teamId) : view.getBoard();
			if (board == null || board.getTiles() == null)
			{
				continue;
			}
			// Group by item, so a drop that fits several tiles gets one line naming them all.
			Map<String, List<ClanData.Tile>> byItem = new java.util.LinkedHashMap<>();
			for (ClanData.Tile tile : board.getTiles())
			{
				String item = matchingItem(tile, items);
				if (item != null)
				{
					byItem.computeIfAbsent(item, k -> new ArrayList<>()).add(tile);
				}
			}
			for (Map.Entry<String, List<ClanData.Tile>> entry : byItem.entrySet())
			{
				List<String> keys = new ArrayList<>();
				List<String> names = new ArrayList<>();
				for (ClanData.Tile tile : entry.getValue())
				{
					keys.add(tileKey(view.getEvent().getId(), teamId, tile.getId()));
					names.add("\"" + tile.getName() + "\"");
				}
				String where = names.size() == 1 ? "counts towards " + names.get(0)
					: "fits " + String.join(", ", names.subList(0, names.size() - 1)) + " and " + names.get(names.size() - 1);
				out.add(new DropMatch(keys, view.getEvent().getName() + ": " + entry.getKey() + " " + where + ". Drop submitted."));
			}
		}
		return out;
	}

	/** The name of the first dropped item that still counts on this tile, or null. */
	private static String matchingItem(ClanData.Tile tile, List<Record.Item> items)
	{
		if (tile.isComplete() || tile.getItems() == null)
		{
			return null;
		}
		for (Record.Item drop : items)
		{
			for (ClanData.TileNeed need : tile.getItems())
			{
				boolean stillNeeded = need.getHave() == null || need.getNeed() == null || need.getHave() < need.getNeed();
				if (need.getItemId() != null && need.getItemId() == drop.getId() && stillNeeded)
				{
					return drop.getName() != null ? drop.getName() : need.getName();
				}
			}
		}
		return null;
	}

	/** Events that went live since the previous view (not on the very first fetch, so a login doesn't repeat them). */
	List<ClanData.Event> newlyLive(ClanView previous)
	{
		if (previous == null || previous.getFetchedAt() == null)
		{
			return List.of();
		}
		Set<String> wasLive = new HashSet<>();
		for (EventView view : previous.live())
		{
			wasLive.add(view.getEvent().getId());
		}
		List<ClanData.Event> out = new ArrayList<>();
		for (EventView view : live())
		{
			if (!wasLive.contains(view.getEvent().getId()))
			{
				out.add(view.getEvent());
			}
		}
		return out;
	}

	/** Signed-up events starting within the reminder window that haven't been reminded yet. */
	List<ClanData.Event> dueReminders(Instant now, Duration window, Set<String> alreadyReminded)
	{
		List<ClanData.Event> out = new ArrayList<>();
		for (EventView view : upcoming())
		{
			ClanData.Event event = view.getEvent();
			Instant start = event.start();
			if (event.isIn() && start != null && !alreadyReminded.contains(event.getId())
				&& start.isAfter(now) && !start.isAfter(now.plus(window)))
			{
				out.add(event);
			}
		}
		return out;
	}

	// ---- formatting ----

	private static final DateTimeFormatter WHEN = DateTimeFormatter.ofPattern("EEE d MMM HH:mm", Locale.UK);

	/** "Mon 26 Oct 14:00" in the member's own time zone. */
	static String localTime(Instant instant, ZoneId zone)
	{
		return instant == null ? "?" : WHEN.format(instant.atZone(zone));
	}

	private static final DateTimeFormatter SHORT_DATE = DateTimeFormatter.ofPattern("d MMM", Locale.UK);
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm", Locale.UK);

	/** "26 Oct", for schedule rows. */
	static String shortDate(Instant instant, ZoneId zone)
	{
		return instant == null ? "?" : SHORT_DATE.format(instant.atZone(zone));
	}

	/** "16:42". */
	static String clock(Instant instant, ZoneId zone)
	{
		return instant == null ? "?" : CLOCK.format(instant.atZone(zone));
	}

	/** "2d 4h", "3h 10m", "12m", "now". */
	static String countdown(Instant from, Instant to)
	{
		if (from == null || to == null)
		{
			return "?";
		}
		long minutes = Duration.between(from, to).toMinutes();
		if (minutes <= 0)
		{
			return "now";
		}
		long days = minutes / (60 * 24);
		long hours = minutes / 60 % 24;
		long mins = minutes % 60;
		if (days > 0)
		{
			return days + "d " + hours + "h";
		}
		if (hours > 0)
		{
			return hours + "h " + mins + "m";
		}
		return mins + "m";
	}

	static String typeLabel(String type)
	{
		if (type == null)
		{
			return "Event";
		}
		switch (type)
		{
			case "botw":
				return "Boss of the week";
			case "sotw":
				return "Skill of the week";
			case "bingo":
				return "Bingo";
			case "competition":
				return "Competition";
			default:
				return "Event";
		}
	}


	/** RSNs from the website without empty entries, so a stray null or blank name can't break the panel. */
	static List<String> names(List<String> names)
	{
		List<String> out = new ArrayList<>();
		for (String name : orEmpty(names))
		{
			if (name != null && !name.trim().isEmpty())
			{
				out.add(name);
			}
		}
		return out;
	}
	static <T> List<T> orEmpty(List<T> list)
	{
		return list == null ? Collections.emptyList() : list;
	}
}

package com.asgardians;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.Value;

/**
 * Gathers the whole collection log. When the collection log opens, the plugin triggers its Search, the game sends every
 * obtained item and runs script 4100 once per item with its ID and quantity (the approach WikiSync and RuneProfile use).
 * The capture is finished once the script has been quiet for a couple of ticks. Client thread only.
 */
class ClogCapture
{
	/** The game script run once per obtained collection log item. */
	static final int ITEM_SCRIPT = 4100;
	/** Runs when the collection log opens; that's when the plugin asks the game for every item. */
	static final int SETUP_SCRIPT = 7797;
	/** Resets the log view after the search, so the member sees their log as normal. */
	static final int INIT_SCRIPT = 2240;
	/** At most one automatic fetch this often. */
	static final long AUTO_FETCH_COOLDOWN_MILLIS = 60_000;
	/** Ticks without another item before the capture counts as complete. */
	static final int QUIET_TICKS = 2;

	@Value
	static class Item
	{
		int id;
		String name;
		int qty;
	}

	private final Map<Integer, Integer> items = new LinkedHashMap<>();
	private int lastItemTick = -1;

	void item(int itemId, int quantity, int tick)
	{
		if (itemId > 0 && quantity > 0)
		{
			items.merge(itemId, quantity, Math::max);
		}
		lastItemTick = tick;
	}

	/** Drops a capture in progress, e.g. when someone else's log is opened from their adventure log. */
	void reset()
	{
		items.clear();
		lastItemTick = -1;
	}

	/**
	 * @return the captured item IDs and quantities once the capture has gone quiet, else null. Clears the capture.
	 */
	Map<Integer, Integer> finishIfQuiet(int tick)
	{
		if (lastItemTick < 0 || tick <= lastItemTick + QUIET_TICKS)
		{
			return null;
		}
		Map<Integer, Integer> done = new LinkedHashMap<>(items);
		reset();
		return done.isEmpty() ? null : done;
	}

	static List<Item> named(Map<Integer, Integer> captured, java.util.function.IntFunction<String> names)
	{
		List<Item> list = new ArrayList<>();
		captured.forEach((id, qty) -> list.add(new Item(id, names.apply(id), qty)));
		return list;
	}
}

package com.asgardians;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import java.util.function.Supplier;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * While a clan event the member is in is live, shows its codeword and the current UTC time. Overlays are part of
 * RuneLite screenshots, so staff can check a drop screenshot was taken during the event.
 */
class CodewordOverlay extends OverlayPanel
{
	private static final DateTimeFormatter UTC = DateTimeFormatter.ofPattern("d MMM HH:mm:ss 'UTC'", Locale.UK)
		.withZone(ZoneOffset.UTC);

	private final AsgardiansConfig config;
	private final Supplier<ClanView> view;

	CodewordOverlay(AsgardiansPlugin plugin, AsgardiansConfig config, Supplier<ClanView> view)
	{
		super(plugin);
		this.config = config;
		this.view = view;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showCodeword())
		{
			return null;
		}
		ClanView current = view.get();
		boolean any = false;
		for (ClanView.EventView live : current.live())
		{
			ClanData.Event event = live.getEvent();
			if (event.getCodeword() == null || !event.isIn())
			{
				continue;
			}
			if (!any)
			{
				panelComponent.getChildren().add(TitleComponent.builder().text("Asgardians").color(PanelParts.HIGHLIGHT).build());
				any = true;
			}
			panelComponent.getChildren().add(LineComponent.builder().left(event.getName()).build());
			panelComponent.getChildren().add(LineComponent.builder().left("Codeword:").right(event.getCodeword())
				.rightColor(PanelParts.HIGHLIGHT).build());
		}
		if (!any)
		{
			return null;
		}
		panelComponent.getChildren().add(LineComponent.builder().left(UTC.format(Instant.now())).build());
		return super.render(graphics);
	}
}

package com.asgardians;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Data;
import lombok.Value;
import net.runelite.api.gameval.ItemID;

/** What a death record carries: who, where, and what it cost. */
@Data
class Death
{
	@Data
	static class Killer
	{
		/** "npc", "player" or "unknown". Player killers are never named. */
		private final String type;
		private final String name;
		private final Integer npcId;
		private final Integer combatLevel;

		static Killer unknown()
		{
			return new Killer("unknown", null, null, null);
		}

		static Killer player()
		{
			return new Killer("player", null, null, null);
		}
	}

	/** A known activity or area, keyed by map region. */
	@Value
	static class Place
	{
		String name;
		/** Items are kept on death here. */
		boolean safe;
	}

	/** Region IDs of activities where deaths are safe, from Dink's WorldUtils (BSD-2-Clause, pajlads). */
	static final Map<Integer, Place> PLACES = places();

	private Killer killer;
	private int regionId;
	private int plane;
	private boolean instanced;
	/** Name of the activity, when the region is a known one. */
	private String area;
	/** Items are kept on a death here (minigames, raids and similar). */
	private boolean safe;
	private boolean wilderness;
	/** Estimated GE value of what was lost: 0 for safe deaths. */
	private long valueLost;
	/** How many items the player keeps on a dangerous death (3, 0 when skulled, +1 with Protect Item, 0 for UIM). */
	private int keepCount;
	private List<Record.Item> lostItems;

	/** One stack the player had at death. */
	@Value
	static class Held
	{
		int id;
		String name;
		int qty;
		long price;
	}

	@Value
	static class Split
	{
		List<Held> kept;
		List<Held> lost;

		long lostValue()
		{
			long total = 0;
			for (Held held : lost)
			{
				total += held.getPrice() * held.getQty();
			}
			return total;
		}
	}

	/** Bonds are always kept and don't use up a kept slot. */
	private static final Set<Integer> ALWAYS_KEPT = Set.of(ItemID.OSRS_BOND, ItemID.BOUGHT_OSRS_BOND, ItemID.OSRS_BOND_UNTRADEABLE);

	/**
	 * Splits what the player held into kept and lost the way the game does for an ordinary dangerous death: the most
	 * valuable single items are kept, one at a time, up to keepCount.
	 */
	static Split split(List<Held> held, int keepCount)
	{
		List<Held> sorted = new ArrayList<>(held);
		sorted.sort(Comparator.comparingLong(Held::getPrice).reversed());
		List<Held> kept = new ArrayList<>();
		List<Held> lost = new ArrayList<>();
		int keptSoFar = 0;
		for (Held stack : sorted)
		{
			if (ALWAYS_KEPT.contains(stack.getId()))
			{
				kept.add(stack);
				continue;
			}
			int keepHere = Math.min(stack.getQty(), keepCount - keptSoFar);
			if (keepHere > 0)
			{
				kept.add(new Held(stack.getId(), stack.getName(), keepHere, stack.getPrice()));
				keptSoFar += keepHere;
			}
			if (stack.getQty() > keepHere)
			{
				lost.add(new Held(stack.getId(), stack.getName(), stack.getQty() - keepHere, stack.getPrice()));
			}
		}
		return new Split(kept, lost);
	}

	private static Map<Integer, Place> places()
	{
		Map<Integer, Place> map = new java.util.HashMap<>();
		add(map, "Chambers of Xeric", 12889, 13136, 13137, 13138, 13139, 13140, 13141, 13145, 13393, 13394, 13395, 13396, 13397, 13401);
