package com.asgardians;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;

/**
 * Turns game events into generic records. It knows nothing about events or bingo: the server decides what each
 * record counts for. Called on the client thread only.
 */
class DropRecorder
{
	/** How close a kill count message must be to its loot to be attached to it. */
	static final long KC_WINDOW_MILLIS = 10_000;
	/** How long after a pet message the clan broadcast can still name it. */
	static final long PET_WINDOW_MILLIS = 10_000;
	/** How far back a new clog slot looks for the loot that caused it, to find its item ID. */
	static final long CLOG_LOOT_WINDOW_MILLIS = 60_000;
	private static final int RECENT = 20;

	/** What the recorder needs from the game's item data. */
	interface Items
	{
		String name(int itemId);

		/** GE price per item. */
		long price(int itemId);

		/** Item ID for an exact item name, or null when it can't be found. */
		Integer idForName(String name);
	}

	private final Items items;
	private final LinkedList<Record> recentLoot = new LinkedList<>();
	private Record lastPet;
	private String lastKcSource;
	private int lastKc;
	private long lastKcMillis;

	DropRecorder(Items items)
	{
		this.items = items;
	}

	/**
	 * @param stacks item ID to quantity, already merged by item
	 */
	Record loot(String sourceName, Integer npcId, Map<Integer, Integer> stacks, Integer partySize, int world, long now)
	{
		List<Record.Item> list = new ArrayList<>();
		long total = 0;
		for (Map.Entry<Integer, Integer> stack : stacks.entrySet())
		{
			int id = stack.getKey();
			int qty = stack.getValue();
			long price = items.price(id);
			list.add(new Record.Item(id, items.name(id), qty, price));
			total += price * qty;
		}
		if (list.isEmpty())
		{
			return null;
		}

		Record record = newRecord(Record.Type.loot, world, now);
		Record.Source source = new Record.Source(sourceName, npcId);
		if (sameSource(lastKcSource, sourceName) && now - lastKcMillis <= KC_WINDOW_MILLIS)
		{
			source.setKc(lastKc);
		}
		record.setSource(source);
		record.setItems(list);
		record.setPartySize(partySize);
		record.totalValue = total;

		recentLoot.addFirst(record);
		while (recentLoot.size() > RECENT)
		{
			recentLoot.removeLast();
		}
		return record;
	}

	/** Kill count messages can arrive just before or just after the loot, so fill in recent loot from the same source too. */
	void killCount(ChatParsers.KillCount kc, long now)
	{
		lastKcSource = kc.getSource();
		lastKc = kc.getCount();
		lastKcMillis = now;
		for (Record record : recentLoot)
		{
			if (now - record.createdMillis > KC_WINDOW_MILLIS)
			{
				break;
			}
			Record.Source source = record.getSource();
			if (source != null && source.getKc() == null && sameSource(source.getName(), kc.getSource()))
			{
				source.setKc(kc.getCount());
			}
		}
	}

	Record pet(boolean duplicate, int world, long now)
	{
		Record record = newRecord(Record.Type.pet, world, now);
		record.setDuplicate(duplicate);
		Record.Source source = lastKcSource != null && now - lastKcMillis <= KC_WINDOW_MILLIS
			? new Record.Source(lastKcSource, null) : null;
		if (source != null)
		{
			source.setKc(lastKc);
		}
		record.setSource(source);
		lastPet = record;
		return record;
	}

	/** Names the most recent pet from the clan broadcast, if it is ours and recent. */
	void clanPet(ChatParsers.ClanPet broadcast, String localRsn, long now)
	{
		if (lastPet != null && lastPet.getPetName() == null && now - lastPet.createdMillis <= PET_WINDOW_MILLIS
			&& sameRsn(broadcast.getRsn(), localRsn))
		{
			lastPet.setPetName(broadcast.getPetName());
		}
	}

	Record clog(String itemName, Integer completed, int world, long now)
	{
		Record record = newRecord(Record.Type.clog, world, now);
		record.setItemName(itemName);
		record.setItemId(findRecentItemId(itemName, now));
		if (record.getItemId() == null)
		{
			record.setItemId(items.idForName(itemName));
		}
		record.setCompleted(completed);
		return record;
	}

	private Integer findRecentItemId(String itemName, long now)
	{
		Iterator<Record> it = recentLoot.iterator();
		while (it.hasNext())
		{
			Record record = it.next();
			if (now - record.createdMillis > CLOG_LOOT_WINDOW_MILLIS)
			{
				break;
			}
			for (Record.Item item : record.getItems())
			{
				if (item.getName().equalsIgnoreCase(itemName))
				{
					return item.getId();
				}
			}
		}
		return null;
	}

	static Record newRecord(Record.Type type, int world, long now)
	{
		Record record = new Record(type, Instant.ofEpochMilli(now).toString(), world);
		record.createdMillis = now;
		return record;
	}

	/** The Gauntlet bosses are recorded under the name of the activity. */
	static String npcLootSource(String npcName)
	{
		switch (npcName)
		{
			case "Crystalline Hunllef":
				return "The Gauntlet";
			case "Corrupted Hunllef":
				return "Corrupted Gauntlet";
			default:
				return npcName;
		}
	}

	/** Kill count messages drop a leading "The" ("Your Gauntlet completion count"), loot sources keep it. */
	static boolean sameSource(String a, String b)
	{
		return a != null && b != null && withoutThe(a).equalsIgnoreCase(withoutThe(b));
	}

	private static String withoutThe(String name)
	{
		return name.regionMatches(true, 0, "The ", 0, 4) ? name.substring(4) : name;
	}

	/** RSNs in chat can use non-breaking spaces or underscores where the player name has spaces. */
	static boolean sameRsn(String a, String b)
	{
		return a != null && b != null && normalise(a).equalsIgnoreCase(normalise(b));
	}

	private static String normalise(String rsn)
	{
		return rsn.replace(' ', ' ').replace('_', ' ').replace('-', ' ').trim();
	}
}

package com.asgardians;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Iterator;
import java.util.Set;
import lombok.Value;
import net.runelite.api.gameval.AnimationID;

/**
 * Spots handegg throws (Easter 2018 eggs from Diango) that the local player is part of. The game says nothing to the
 * player who's hit, so this goes by animations: a player throws an egg, and another plays the catch animation. The
 * two can arrive in either order within a tick, so each is held for a few ticks waiting for the other. Catching is a
 * generic animation, so it only counts next to a throw by someone else.
 */
class EggTracker
{
	/** Holy, peaceful and chaotic handegg throws. */
	static final Set<Integer> THROWS = Set.of(AnimationID.HUMAN_THROW_EGG_SARA, AnimationID.HUMAN_THROW_EGG_GUTHIX,
		AnimationID.HUMAN_THROW_EGG_ZAM);
	static final int CATCH = AnimationID.HUMAN_CATCH;
	/** How long an egg can be in the air, in game ticks. */
	static final int WINDOW_TICKS = 8;

	@Value
	static class Egg
	{
		String thrower;
		String target;
	}

	@Value
	private static class Seen
	{
		String name;
		int tick;
	}

	private final Deque<Seen> throwsSeen = new ArrayDeque<>();
	private final Deque<Seen> catchesSeen = new ArrayDeque<>();

	static boolean isEggAnimation(int animation)
	{
		return animation == CATCH || THROWS.contains(animation);
	}

	/**
	 * Called when any player starts an animation.
	 *
	 * @return the egging, when this throw or catch completes one the local player threw or was hit by; otherwise null
	 */
	Egg animation(String actor, int animation, int tick, String me)
	{
		String name = clean(actor);
		throwsSeen.removeIf(s -> tick - s.getTick() > WINDOW_TICKS || s.getTick() > tick);
		catchesSeen.removeIf(s -> tick - s.getTick() > WINDOW_TICKS || s.getTick() > tick);
		if (name == null || me == null || !isEggAnimation(animation))
		{
			return null;
		}
		boolean isThrow = THROWS.contains(animation);
		// A throw pairs with the latest catch by someone else, and a catch with the latest throw. Each is used once.
		Seen other = takeLatestNotBy(isThrow ? catchesSeen : throwsSeen, name);
		if (other == null)
		{
			(isThrow ? throwsSeen : catchesSeen).addLast(new Seen(name, tick));
			return null;
		}
		Egg egg = isThrow ? new Egg(name, other.getName()) : new Egg(other.getName(), name);
		boolean mine = DropRecorder.sameRsn(egg.getThrower(), me) || DropRecorder.sameRsn(egg.getTarget(), me);
		return mine ? egg : null;
	}

	private static Seen takeLatestNotBy(Deque<Seen> seen, String name)
	{
		Iterator<Seen> it = seen.descendingIterator();
		while (it.hasNext())
		{
			Seen s = it.next();
			if (!DropRecorder.sameRsn(s.getName(), name))
			{
				it.remove();
				return s;
			}
		}
		return null;
	}

	void clear()
	{
		throwsSeen.clear();
		catchesSeen.clear();
	}

	/** Player names can carry non-breaking spaces. */
	private static String clean(String name)
	{
		if (name == null)
		{
			return null;
		}
		String cleaned = name.replace(' ', ' ').trim();
		return cleaned.isEmpty() ? null : cleaned;
	}
}

package com.asgardians;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.function.BooleanSupplier;
import java.util.function.LongSupplier;
import lombok.Value;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Shows new groups on screen for a short while, for the activities the member has the screen icon on for in the
 * Groups tab's "Group alerts". The newest is at the top, and only a few show at once.
 */
class GroupAlertOverlay extends OverlayPanel
{
	static final long SHOW_MILLIS = 20_000;
	static final int MAX_SHOWN = 3;

	@Value
	static class Alert
	{
		String host;
		String title;
		String seats;
		String world;
		long until;
	}

	private final BooleanSupplier enabled;
	private final LongSupplier clock;
	private final Deque<Alert> alerts = new ArrayDeque<>();

	GroupAlertOverlay(AsgardiansPlugin plugin, BooleanSupplier enabled, LongSupplier clock)
	{
		super(plugin);
		this.enabled = enabled;
		this.clock = clock;
		setPosition(OverlayPosition.TOP_CENTER);
		// Wide enough for "Theatre of Blood (Hard mode)" on one line; RuneLite's default wraps it.
		panelComponent.setPreferredSize(new Dimension(WIDTH, 0));
	}

	static final int WIDTH = 210;

	synchronized void add(ClanData.Group g)
	{
		add(g, g.getTitle());
	}

	/** @param title the group's title, short where the website gives short names */
	synchronized void add(ClanData.Group g, String title)
	{
		alerts.addFirst(new Alert(g.getHost() != null ? g.getHost() : "Someone", title, g.seats(), Groups.world(g),
			clock.getAsLong() + SHOW_MILLIS));
		while (alerts.size() > MAX_SHOWN)
		{
			alerts.removeLast();
		}
	}

	synchronized void clear()
	{
		alerts.clear();
	}

	/** The alerts still showing, newest first. */
	synchronized List<Alert> showing()
	{
		long now = clock.getAsLong();
		alerts.removeIf(a -> a.getUntil() <= now);
		return new ArrayList<>(alerts);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<Alert> shown = showing();
		if (!enabled.getAsBoolean() || shown.isEmpty())
		{
			return null;
		}
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(shown.size() == 1 ? "New clan group" : "New clan groups").color(PanelParts.HIGHLIGHT).build());
		for (Alert a : shown)
		{
			panelComponent.getChildren().add(LineComponent.builder().left(a.getTitle()).right(a.getSeats())
				.rightColor(PanelParts.HIGHLIGHT).build());
			panelComponent.getChildren().add(LineComponent.builder().left(a.getHost()).right(a.getWorld())
				.leftColor(PanelParts.QUIET).rightColor(PanelParts.QUIET).build());
		}
		panelComponent.getChildren().add(LineComponent.builder().left("Join from the Groups tab").leftColor(PanelParts.QUIET).build());
		return super.render(graphics);
	}
}

package com.asgardians;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.GeneralPath;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import javax.swing.Icon;

/**
 * Which group activities the member hears about in chat when a clanmate starts a group. The website decides, per
 * activity, whether it's up to the member ("on" or "off" by default) or sent to everyone ("always"). The member's own
 * choices are saved as "id=1,id=0".
 */
final class GroupBells
{
	static final String ON = "on";
	static final String OFF = "off";
	static final String ALWAYS = "always";

	private GroupBells()
	{
	}

	/** The website's setting for an activity: on, off or always. Anything else counts as on. */
	static String mode(ClanData.GroupActivity activity)
	{
		String alerts = activity != null && activity.getAlerts() != null ? activity.getAlerts().trim().toLowerCase(Locale.UK) : "";
		return OFF.equals(alerts) || ALWAYS.equals(alerts) ? alerts : ON;
	}

	/**
	 * Whether a new group for this activity is announced to the member.
	 *
	 * @param choices  the member's bells, by activity ID
	 * @param alertsOn the "New groups in chat" setting; off silences every activity the member can choose about
	 */
	static boolean rings(ClanData.GroupActivity activity, Map<String, Boolean> choices, boolean alertsOn)
	{
		String mode = mode(activity);
		if (ALWAYS.equals(mode))
		{
			return true;
		}
		return alertsOn && bell(activity, choices);
	}

	/** The bell as shown: the member's choice, or the website's default when they haven't chosen. */
	static boolean bell(ClanData.GroupActivity activity, Map<String, Boolean> choices)
	{
		String mode = mode(activity);
		if (ALWAYS.equals(mode))
		{
			return true;
		}
		Boolean chosen = activity != null && activity.getId() != null && choices != null ? choices.get(activity.getId()) : null;
		return chosen != null ? chosen : ON.equals(mode);
	}

	/**
	 * Whether a new group for this activity also shows on screen: only when it rings, the "New groups on screen"
	 * setting is on, and the member hasn't turned the activity's screen icon off (it's on until they do).
	 */
	static boolean onScreen(ClanData.GroupActivity activity, Map<String, Boolean> choices, Map<String, Boolean> screens,
		boolean alertsOn, boolean screenOn)
	{
		return screenOn && rings(activity, choices, alertsOn) && screen(activity, screens);
	}

	/** The screen icon as shown: the member's choice, otherwise on. */
	static boolean screen(ClanData.GroupActivity activity, Map<String, Boolean> screens)
	{
		Boolean chosen = activity != null && activity.getId() != null && screens != null ? screens.get(activity.getId()) : null;
		return chosen == null || chosen;
	}

	static Map<String, Boolean> parse(String saved)
	{
		Map<String, Boolean> out = new LinkedHashMap<>();
		if (saved == null)
		{
			return out;
		}
		for (String part : saved.split(","))
		{
			int eq = part.lastIndexOf('=');
			if (eq > 0)
			{
				String id = part.substring(0, eq).trim();
				String value = part.substring(eq + 1).trim();
				if (!id.isEmpty() && ("1".equals(value) || "0".equals(value)))
				{
					out.put(id, "1".equals(value));
				}
			}
		}
		return out;
	}

	static String format(Map<String, Boolean> choices)
	{
		StringBuilder out = new StringBuilder();
		for (Map.Entry<String, Boolean> e : choices.entrySet())
		{
			// IDs come from the website; leave out any that would break the saved format.
			if (e.getKey() != null && e.getValue() != null && !e.getKey().contains(",") && !e.getKey().contains("="))
			{
				out.append(out.length() > 0 ? "," : "").append(e.getKey()).append('=').append(e.getValue() ? '1' : '0');
			}
		}
		return out.toString();
	}

	/** A small screen: orange when new groups show on screen, grey and struck through when not, dim when it can't. */
	static final class ScreenIcon implements Icon
	{
		private static final Color MUTED = new Color(0x70, 0x70, 0x70);
		private static final Color DIM = new Color(0x48, 0x48, 0x48);
		private final Color colour;
		private final boolean struck;

		ScreenIcon(boolean on, boolean usable)
		{
			this.colour = !usable ? DIM : on ? PanelParts.HIGHLIGHT : MUTED;
			this.struck = !on && usable;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.translate(x, y);
			g2.setColor(colour);
			g2.setStroke(new BasicStroke(1.6f));
			g2.drawRoundRect(1, 2, 12, 8, 2, 2);
			g2.fillRect(3, 4, 8, 4);
			g2.fillRect(6, 10, 2, 2);
			g2.fillRect(4, 12, 6, 1);
			if (struck)
			{
				g2.setColor(PanelParts.TEXT);
				g2.drawLine(1, 13, 13, 1);
			}
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return 14;
		}

		@Override
		public int getIconHeight()
		{
			return 14;
		}
	}

	/** A bell, drawn since the game fonts have none: orange when ringing, grey and struck through when muted. */
	static final class BellIcon implements Icon
	{
		private static final Color MUTED = new Color(0x70, 0x70, 0x70);
		private final Color colour;
		private final boolean struck;

		BellIcon(boolean on, boolean locked)
		{
			this.colour = locked ? PanelParts.TEST_SERVER : on ? PanelParts.HIGHLIGHT : MUTED;
			this.struck = !on;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.translate(x, y);
			g2.setColor(colour);
			GeneralPath bell = new GeneralPath();
			bell.moveTo(7, 1.5);
			bell.curveTo(3.5, 1.5, 3, 4.5, 3, 7.5);
			bell.lineTo(3, 9.5);
			bell.lineTo(1.5, 11.5);
			bell.lineTo(12.5, 11.5);
			bell.lineTo(11, 9.5);
			bell.lineTo(11, 7.5);
			bell.curveTo(11, 4.5, 10.5, 1.5, 7, 1.5);
			bell.closePath();
			g2.fill(bell);
			g2.fillOval(5, 11, 4, 3);
			if (struck)
			{
				g2.setStroke(new BasicStroke(1.6f));
				g2.setColor(PanelParts.TEXT);
				g2.drawLine(1, 13, 13, 1);
			}
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return 14;
		}

		@Override
		public int getIconHeight()
		{
			return 14;
		}
	}
}

package com.asgardians;

import static com.asgardians.PanelParts.Card;
