		heading.setVerticalTextPosition(JLabel.TOP);
		heading.setFont(FontManager.getRunescapeBoldFont());
		heading.setForeground(TEXT);
		row.add(heading, BorderLayout.CENTER);
		if (right != null)
		{
			row.add(plain(right, HIGHLIGHT), BorderLayout.EAST);
		}
		row.setToolTipText(open ? "Click to fold away" : "Click to open");
		row.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
		row.addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mousePressed(java.awt.event.MouseEvent e)
			{
				toggle.run();
			}

			@Override
			public void mouseEntered(java.awt.event.MouseEvent e)
			{
				heading.setForeground(HIGHLIGHT);
			}

			@Override
			public void mouseExited(java.awt.event.MouseEvent e)
			{
				heading.setForeground(TEXT);
			}
		});
		return row;
	}

	/** A small triangle, pointing down when open and right when folded. Drawn, since the game fonts have no arrows. */
	private static class Arrow implements javax.swing.Icon
	{
		private final boolean open;

		Arrow(boolean open)
		{
			this.open = open;
		}

		@Override
		public void paintIcon(Component c, java.awt.Graphics g, int x, int y)
		{
			java.awt.Graphics2D g2 = (java.awt.Graphics2D) g.create();
			g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(QUIET);
			int[] xs = open ? new int[]{x, x + 8, x + 4} : new int[]{x + 1, x + 7, x + 1};
			int[] ys = open ? new int[]{y + 2, y + 2, y + 7} : new int[]{y, y + 4, y + 8};
			g2.fillPolygon(xs, ys, 3);
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return 8;
		}

		@Override
		public int getIconHeight()
		{
			return 9;
		}
	}

	static JButton button(String text, Runnable action)
	{
		return button(text, false, action);
	}

	/** A themed button; {@code primary} ones are solid orange. */
	static JButton button(String text, boolean primary, Runnable action)
	{
		JButton button = new JButton(text)
		{
			@Override
			protected void paintComponent(java.awt.Graphics g)
			{
				boolean hover = getModel().isRollover() && isEnabled();
				Color fill = primary ? (hover ? HIGHLIGHT.brighter() : HIGHLIGHT) : hover ? CARD_HOVER : CARD;
				roundBox(g, getWidth(), getHeight(), isEnabled() ? fill : CARD, primary ? null : hover ? HIGHLIGHT : LINE);
				super.paintComponent(g);
			}
		};
		button.setContentAreaFilled(false);
		button.setBorderPainted(false);
		button.setOpaque(false);
		button.setFocusPainted(false);
		button.setFont(FontManager.getRunescapeBoldFont());
		button.setForeground(primary ? ON_HIGHLIGHT : TEXT);
		button.setBorder(new EmptyBorder(5, 8, 5, 8));
		button.setRolloverEnabled(true);
		button.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
		button.addActionListener(e -> action.run());
		return button;
	}

	static String wrap(String html)
	{
		return "<html><div style='width:" + TEXT_WIDTH + "px'>" + html + "</div></html>";
	}

	static String dot(Color colour)
	{
		return "<span style='color:" + hex(colour) + "'>●</span>";
	}

	static String hex(Color colour)
	{
		return String.format("#%02x%02x%02x", colour.getRed(), colour.getGreen(), colour.getBlue());
	}

	static String escape(String text)
	{
		return text == null ? "" : text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.asgardians;

import java.util.ArrayList;
import java.util.List;

/**
 * Decides what to do when RuneLite's stored PBs change. Pure logic so it can be tested; the plugin feeds it events.
 *
 * <p>RuneLite's Chat Commands plugin parses every PB message and the Adventure Log counters page and writes the result
 * to its "personalbest" store. Mirroring that store means the plugin tracks exactly what RuneLite shows, including
 * team sizes and precise times, without parsing the messages a second time.
 */
class PbTracker
{
	/** A store change this close to a "(new personal best)" message is a live PB. */
	static final long NEW_PB_WINDOW_MILLIS = 10_000;
	/** Other changes (Adventure Log counters, corrections) are gathered and sent as one full sync this long after the last. */
	static final long SYNC_DEBOUNCE_MILLIS = 5_000;

	interface Store
	{
		/** Every key in the current account's "personalbest" store. */
		List<String> keys();

		String value(String key);

		/** Kill count RuneLite stores for a boss, or null. */
		Integer killCount(String boss);
	}

	private final Store store;
	private long lastNewPbMessage = -NEW_PB_WINDOW_MILLIS - 1;
	private long syncDueAt = -1;

	PbTracker(Store store)
	{
		this.store = store;
	}

	/** Call for every game message; remembers when the last "(new personal best)" was seen. */
	void chatMessage(String message, long now)
	{
		if (message.contains("(new personal best)"))
		{
			lastNewPbMessage = now;
		}
	}

	/**
	 * Call when RuneLite's "personalbest" store changes for the logged-in account.
	 *
	 * @return the PB to send right away as a record, or null when it will go in the next full sync instead
	 */
	PersonalBest changed(String key, String newValue, long now)
	{
		PersonalBest pb = PersonalBest.parse(key, newValue);
		if (pb == null)
		{
			return null;
		}
		if (now - lastNewPbMessage <= NEW_PB_WINDOW_MILLIS)
		{
			pb.setNewPb(true);
			pb.setKc(store.killCount(pb.getBoss()));
			return pb;
		}
		requestSync(now);
		return null;
	}

	/** Schedules a full sync after the debounce, pushing it back if one is already waiting. */
	void requestSync(long now)
	{
		syncDueAt = now + SYNC_DEBOUNCE_MILLIS;
	}

	/** Schedules a full sync straight away (login, button). */
	void requestSyncNow(long now)
	{
		syncDueAt = now;
	}

	boolean syncDue(long now)
	{
		return syncDueAt >= 0 && now >= syncDueAt;
	}

	void syncStarted()
	{
		syncDueAt = -1;
	}

	/** Every PB in the store, with kill counts. */
	List<PersonalBest> snapshot()
	{
		List<PersonalBest> all = new ArrayList<>();
		for (String key : store.keys())
		{
			PersonalBest pb = PersonalBest.parse(key, store.value(key));
			if (pb != null)
			{
				pb.setKc(store.killCount(pb.getBoss()));
				all.add(pb);
			}
		}
		return all;
	}
}

package com.asgardians;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Data;

/**
 * One personal best as RuneLite's Chat Commands plugin stores it: config group "personalbest", RS profile scoped,
 * key = lowercase boss name with an optional team size suffix ("chambers of xeric 3 players", "theatre of blood solo"),
 * value = seconds.
 */
@Data
class PersonalBest
{
	static final String CONFIG_GROUP = "personalbest";
	static final String KC_CONFIG_GROUP = "killcount";

	/** "solo", "3 players", "11-15 players", "24+ players". */
	private static final Pattern TEAM_SUFFIX = Pattern.compile("^(.+?) (solo|\\d+(?:-\\d+|\\+)? players)$");
	private static final double TICK_SECONDS = 0.6;

	/** RuneLite's key, exactly as stored. Unique per boss and team size. */
	private final String key;
	/** The key without its team size. */
	private final String boss;
	/** "1" for solo, "3", "11-15", "24+"; null when the PB isn't for a team size. */
	private final String teamSize;
	private final double seconds;
	/** Game ticks, when the time is precise and a whole number of ticks. */
	private final Integer ticks;
	/** False when the time is whole seconds, which may be a rounded (non-precise) time. */
	private final boolean precise;
	private Integer kc;
	/** True when this came from a "(new personal best)" message just now, rather than a sync. */
	private boolean newPb;

	static PersonalBest of(String key, double seconds)
	{
		String boss = key;
		String teamSize = null;
		Matcher m = TEAM_SUFFIX.matcher(key);
		if (m.matches())
		{
			boss = m.group(1);
			String suffix = m.group(2);
			teamSize = suffix.equals("solo") ? "1" : suffix.substring(0, suffix.length() - " players".length());
		}
		boolean precise = seconds != Math.floor(seconds);
		Integer ticks = null;
		if (precise)
		{
			double t = seconds / TICK_SECONDS;
			long rounded = Math.round(t);
			if (Math.abs(t - rounded) < 0.02)
			{
				ticks = (int) rounded;
			}
		}
		return new PersonalBest(key, boss, teamSize, seconds, ticks, precise);
	}

	/** Parses a stored value, or returns null for anything that isn't a positive number of seconds. */
	static PersonalBest parse(String key, String value)
	{
		if (key == null || value == null)
		{
			return null;
		}
		try
		{
			double seconds = Double.parseDouble(value);
			return seconds > 0 ? of(key, seconds) : null;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	String display()
	{
		int whole = (int) seconds;
		String time = whole >= 3600
			? String.format("%d:%02d:%02d", whole / 3600, whole / 60 % 60, whole % 60)
			: String.format("%d:%02d", whole / 60, whole % 60);
		if (precise)
		{
			time += String.format(".%02d", Math.round((seconds - whole) * 100) % 100);
		}
		return key + " " + time;
	}
}

package com.asgardians;

import static com.asgardians.PanelParts.BAD;
import static com.asgardians.PanelParts.Card;
import static com.asgardians.PanelParts.GOLD;
import static com.asgardians.PanelParts.GOOD;
import static com.asgardians.PanelParts.HIGHLIGHT;
import static com.asgardians.PanelParts.QUIET;
import static com.asgardians.PanelParts.TEXT;
import static com.asgardians.PanelParts.TODO;
import static com.asgardians.PanelParts.addCard;
import static com.asgardians.PanelParts.small;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import java.time.Instant;
import java.util.List;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import lombok.Value;
import net.runelite.client.ui.FontManager;

/**
 * A clan profile: who they are (rank, time in the clan, Discord), Clan credit, EHB and EHP, their clan rankings, events,
 * personal bests, collection log and pets, drops, deaths and handeggs. Used for the member's own profile and for
 * clanmates'. Sections the website doesn't send are left out. Swing thread.
 */
final class ProfileTabs
{
	@Value
	static class Input
	{
		String rsn;
		/** Null while loading, or when the website has no profile for them. */
		ClanData.Me me;
		/** The member's own profile. */
		boolean own;
		boolean loading;
		/** The website doesn't have clanmates' profiles yet. */
		boolean unsupported;
		/** Null when offline. */
		Integer world;
		String activity;
		/** Leaderboard places this month. */
		List<ClanData.ProfileRank> rankings;
		/** Their latest drops from the clan feed. */
		List<ClanData.StatEntry> recentDrops;
		Instant now;
	}

	interface Actions
	{
		/** Opens the Leaderboard on this board, this month. */
		void openBoard(String board);

		/** Puts the boss's icon on the label. */
		void bossIcon(JLabel label, String boss);
	}

	private ProfileTabs()
	{
	}

	static void draw(JPanel column, Input in, Actions actions)
	{
		ClanData.Me me = in.getMe();
		addCard(column, identity(in));
		if (me == null)
		{
			Card card = new Card(null);
			card.add(small(in.isLoading() ? "Loading their profile…"
				: in.isUnsupported() ? "Full profiles of clanmates aren't on the clan website yet."
				: "No clan profile yet.", QUIET));
			addCard(column, card);
			return;
		}

		// Discord
		Card discord = new Card(null);
		discord.setBorder(new EmptyBorder(6, 8, 6, 8));
		discord.addWide(PanelParts.spread(PanelParts.plain("Discord", QUIET),
			PanelParts.plain(me.isDiscordLinked() ? "Linked" : "Not linked", me.isDiscordLinked() ? GOOD : QUIET)));
		String help = in.isOwn() ? ProfileText.discordHelp(me) : null;
		if (help != null)
		{
			discord.add(small(help, TODO));
		}
		addCard(column, discord);

		// Clan credit, EHB, EHP
		JPanel boxes = new JPanel(new GridLayout(1, 3, 4, 0));
		boxes.setOpaque(false);
		boxes.add(statBox(me.getSplitCredit() != null ? ProfileText.amount(me.getSplitCredit()) : "–", "Clan credit", HIGHLIGHT));
		boxes.add(statBox(me.getEhb() != null ? whole(me.getEhb()) : "–", "EHB", HIGHLIGHT));
		boxes.add(statBox(me.getEhp() != null ? whole(me.getEhp()) : "–", "EHP", HIGHLIGHT));
		boxes.setMaximumSize(new java.awt.Dimension(Integer.MAX_VALUE, boxes.getPreferredSize().height));
		addCard(column, boxes);

		String next = in.isOwn() ? ProfileText.nextRank(me) : null;
		if (next != null || me.isHeld())
		{
			Card rank = new Card(null);
			if (next != null)
			{
				rank.add(small(next, TODO));
			}
			if (me.isHeld())
			{
				rank.add(PanelParts.status(BAD, "Your account is held for staff review."));
			}
			addCard(column, rank);
		}

		// Clan rankings
		List<ClanData.ProfileRank> ranks = in.getRankings() != null && !in.getRankings().isEmpty() ? in.getRankings() : me.getRankings();
		if (ranks != null && !ranks.isEmpty())
		{
			section(column, "Clan rankings · this month");
			for (ClanData.ProfileRank r : ranks)
			{
				if (r == null || r.getBoard() == null)
				{
					continue;
				}
				Card row = new Card(null);
				row.setBorder(new EmptyBorder(4, 8, 4, 8));
				JPanel line = new JPanel(new BorderLayout(6, 0));
				line.setOpaque(false);
				line.add(PanelParts.cut(r.getBoard(), TEXT), BorderLayout.CENTER);
				JPanel right = new JPanel(new java.awt.FlowLayout(java.awt.FlowLayout.RIGHT, 8, 0));
				right.setOpaque(false);
				if (r.getRank() != null)
				{
					right.add(PanelParts.bold("#" + r.getRank(), r.getRank() == 1 ? GOLD : HIGHLIGHT));
				}
				if (r.getValue() != null)
				{
					right.add(PanelParts.plain(r.getValue(), QUIET));
				}
				line.add(right, BorderLayout.EAST);
				row.addWide(line);
				row.onClick(() -> actions.openBoard(r.getBoard()), "Open the " + r.getBoard() + " board");
				gap(column, 4);
				row.setAlignmentX(JPanel.LEFT_ALIGNMENT);
				column.add(row);
			}
		}

		// Events
		if (me.getEvents() != null && !me.getEvents().isEmpty())
		{
			section(column, "Events");
			for (ClanData.EventResult e : me.getEvents())
			{
				if (e == null || e.getName() == null)
				{
					continue;
				}
				Card card = new Card(null);
				card.setBorder(new EmptyBorder(5, 8, 5, 8));
				card.add(PanelParts.bold(e.getName(), TEXT));
				if (e.getResult() != null)
				{
					card.add(PanelParts.plain(e.getResult(), e.isWon() ? GOLD : QUIET));
				}
				gap(column, 4);
				card.setAlignmentX(JPanel.LEFT_ALIGNMENT);
				column.add(card);
			}
		}

		// Personal bests
		if (me.getPersonalBests() != null && !me.getPersonalBests().isEmpty())
		{
			section(column, "Personal bests");
			Card card = new Card(null);
			card.setBorder(new EmptyBorder(5, 8, 5, 8));
			int shown = 0;
			for (ClanData.StatEntry pb : me.getPersonalBests())
			{
				if (pb == null || pb.getBoss() == null || shown++ >= 8)
				{
					continue;
				}
				JPanel line = new JPanel(new BorderLayout(6, 0));
				line.setOpaque(false);
				line.setBorder(new EmptyBorder(1, 0, 1, 0));
				JLabel icon = new JLabel();
				icon.setPreferredSize(new java.awt.Dimension(20, 20));
				actions.bossIcon(icon, pb.getBoss());
				line.add(icon, BorderLayout.WEST);
				line.add(PanelParts.cut(StatsTabs.name(pb, StatsTabs.PBS), TEXT), BorderLayout.CENTER);
				line.add(PanelParts.plain(StatsTabs.right(pb, StatsTabs.PBS), HIGHLIGHT), BorderLayout.EAST);
				card.addWide(line);
			}
			addCard(column, card);
		}

		// Collection log and pets
		if (me.getClogObtained() != null || (me.getPets() != null && !me.getPets().isEmpty()))
		{
			section(column, "Collection log");
			Card card = new Card(null);
			if (me.getClogObtained() != null)
			{
				if (me.getClogTotal() != null && me.getClogTotal() > 0)
				{
					card.addWide(PanelParts.progress(me.getClogObtained(), me.getClogTotal(),
						String.format("%,d / %,d", me.getClogObtained(), me.getClogTotal())));
				}
				else
				{
					card.add(PanelParts.plain(String.format("%,d slots", me.getClogObtained()), TEXT));
				}
			}
			if (me.getPets() != null && !me.getPets().isEmpty())
			{
				card.gap();
				JPanel pets = new JPanel(new java.awt.FlowLayout(java.awt.FlowLayout.LEFT, 3, 0));
				pets.setOpaque(false);
				pets.add(PanelParts.plain("Pets", QUIET));
				for (ClanData.ProfileItem pet : me.getPets().subList(0, Math.min(8, me.getPets().size())))
				{
					JLabel box = PanelParts.itemBox(pet.getItemId(), 20);
					box.setToolTipText(pet.getName());
					pets.add(box);
				}
				card.addWide(pets);
			}
			addCard(column, card);
		}

		// Drops record
		if (me.getDrops() != null || me.getDropValue() != null)
		{
			section(column, "Drops record");
			JPanel row = new JPanel(new GridLayout(1, 3, 4, 0));
			row.setOpaque(false);
			row.add(statBox(me.getDrops() != null ? String.format("%,d", me.getDrops()) : "–", "Logged", TEXT));
			row.add(statBox(me.getDropValue() != null ? ProfileText.amount(me.getDropValue()) : "–", "Total value", GOLD));
			row.add(statBox(me.getPets() != null ? String.valueOf(me.getPets().size()) : "–", "Pets", TEXT));
			row.setMaximumSize(new java.awt.Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
			gap(column, 4);
			row.setAlignmentX(JPanel.LEFT_ALIGNMENT);
			column.add(row);
		}

		// Deaths
		if (me.getDeaths() != null)
		{
			section(column, "Deaths");
			Card card = new Card(null);
			JPanel top = new JPanel(new java.awt.FlowLayout(java.awt.FlowLayout.LEFT, 0, 0));
			top.setOpaque(false);
			top.add(PanelParts.bold(String.format("%,d", me.getDeaths()), BAD));
			top.add(PanelParts.plain(" deaths", QUIET));
			card.addWide(top);
			if (me.getLastDeathBy() != null)
			{
				String ago = me.lastDeath() != null ? " · " + ClanView.ago(me.lastDeath(), in.getNow()) : "";
				card.add(PanelParts.plain("Last: " + me.getLastDeathBy() + ago, TEXT));
			}
			if (me.getTopKiller() != null)
			{
				card.add(PanelParts.plain("Top killer: " + me.getTopKiller(), QUIET));
			}
			addCard(column, card);
		}

		// Handeggs
		if (me.getEggsThrown() != null || me.getEggsReceived() != null)
		{
			section(column, "Handeggs");
			Card card = new Card(null);
			card.setBorder(new EmptyBorder(6, 8, 6, 8));
			card.addWide(PanelParts.spread(
				PanelParts.plain("Egged " + (me.getEggsThrown() != null ? me.getEggsThrown() : 0), TEXT),
				PanelParts.plain("Got egged " + (me.getEggsReceived() != null ? me.getEggsReceived() : 0), QUIET)));
			addCard(column, card);
		}

		// Recent drops
		if (in.getRecentDrops() != null && !in.getRecentDrops().isEmpty())
		{
			section(column, "Recent drops");
			for (ClanData.StatEntry e : in.getRecentDrops().subList(0, Math.min(5, in.getRecentDrops().size())))
			{
				Card card = new Card(null);
				card.setBorder(new EmptyBorder(5, 6, 5, 8));
				JPanel line = new JPanel(new BorderLayout(6, 0));
				line.setOpaque(false);
				line.add(PanelParts.itemBox(e.getItemId(), 28), BorderLayout.WEST);
				JPanel words = new JPanel();
				words.setLayout(new BoxLayout(words, BoxLayout.Y_AXIS));
				words.setOpaque(false);
				JPanel top = new JPanel(new BorderLayout(4, 0));
				top.setOpaque(false);
				top.add(PanelParts.cut(StatsTabs.name(e, StatsTabs.DROPS), TEXT), BorderLayout.CENTER);
				String value = StatsTabs.right(e, StatsTabs.DROPS);
				if (!value.isEmpty())
				{
					top.add(PanelParts.plain(value, GOLD), BorderLayout.EAST);
				}
				top.setAlignmentX(JPanel.LEFT_ALIGNMENT);
				words.add(top);
				JLabel when = PanelParts.cut((e.getSource() != null ? e.getSource() + " · " : "") + ClanView.ago(e.time(), in.getNow()), QUIET);
				when.setAlignmentX(JPanel.LEFT_ALIGNMENT);
				words.add(when);
				line.add(words, BorderLayout.CENTER);
				card.addWide(line);
				gap(column, 4);
				card.setAlignmentX(JPanel.LEFT_ALIGNMENT);
				column.add(card);
			}
		}
	}

	/** Picture, name and rank, where they are, and how long they've been in the clan. */
	private static Card identity(Input in)
	{
		ClanData.Me me = in.getMe();
		Card card = new Card(null).outlined(in.isOwn() ? new Color(0x6E, 0x37, 0x15) : PanelParts.LINE, PanelParts.CARD);
		JPanel row = new JPanel(new BorderLayout(8, 0));
		row.setOpaque(false);
		Integer picture = ActivityTracker.icon(in.getActivity());
		if (picture == null && me != null && me.getPets() != null && !me.getPets().isEmpty())
		{
			picture = me.getPets().get(0).getItemId();
		}
		JLabel avatar = PanelParts.itemBox(picture, 40);
		if (picture == null)
		{
			avatar.setIcon(new PersonIcon());
		}
		row.add(avatar, BorderLayout.WEST);
		JPanel words = new JPanel();
		words.setLayout(new BoxLayout(words, BoxLayout.Y_AXIS));
		words.setOpaque(false);
		JPanel name = new JPanel(new java.awt.FlowLayout(java.awt.FlowLayout.LEFT, 0, 0));
		name.setOpaque(false);
		name.add(PanelParts.bold(in.getRsn(), TEXT));
		if (me != null && me.getRank() != null)
		{
			name.add(Box.createHorizontalStrut(5));
			name.add(PanelParts.tag(ProfileText.rank(me.getRank()), GOLD));
		}
		name.setAlignmentX(JPanel.LEFT_ALIGNMENT);
		words.add(name);
		JPanel status = new JPanel(new BorderLayout(4, 0));
		status.setOpaque(false);
		boolean online = in.getWorld() != null;
		status.add(PanelParts.dotIcon(online ? GOOD : PanelParts.LINE), BorderLayout.WEST);
		String where = online ? "W" + in.getWorld() + (in.getActivity() != null ? " · " + in.getActivity() : "") : "Offline";
		status.add(PanelParts.cut(where, online ? TEXT : QUIET), BorderLayout.CENTER);
		status.setAlignmentX(JPanel.LEFT_ALIGNMENT);
		words.add(status);
		if (me != null && me.getDaysInClan() != null)
		{
			JLabel time = PanelParts.cut("In clan " + ProfileText.time(me.getDaysInClan()), QUIET);
			time.setAlignmentX(JPanel.LEFT_ALIGNMENT);
			words.add(time);
		}
		row.add(words, BorderLayout.CENTER);
		card.addWide(row);
		return card;
	}

	/** A number with its name under it, on the panel's background. */
	static JPanel statBox(String value, String label, Color colour)
	{
		JPanel box = new JPanel()
		{
			@Override
			protected void paintComponent(java.awt.Graphics g)
			{
				PanelParts.roundBox(g, getWidth(), getHeight(), PanelParts.CARD, null);
				super.paintComponent(g);
			}
		};
		box.setLayout(new BoxLayout(box, BoxLayout.Y_AXIS));
		box.setOpaque(false);
		box.setBorder(new EmptyBorder(6, 2, 6, 2));
		JLabel v = new JLabel(value, JLabel.CENTER);
		v.setFont(FontManager.getRunescapeBoldFont());
		v.setForeground(colour);
		v.setAlignmentX(0.5f);
		JLabel l = new JLabel(label, JLabel.CENTER);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(QUIET);
		l.setAlignmentX(0.5f);
		box.add(v);
		box.add(l);
		return box;
	}

	private static String whole(double v)
	{
		return String.format("%,d", Math.round(v));
	}

	private static void section(JPanel column, String text)
	{
		column.add(Box.createVerticalStrut(PanelParts.GAP + 2));
		JLabel label = PanelParts.section(text);
		label.setAlignmentX(JPanel.LEFT_ALIGNMENT);
		column.add(label);
	}

	private static void gap(JPanel column, int h)
	{
		column.add(Box.createVerticalStrut(h));
	}

	/** A head and shoulders in orange, for someone with no picture. */
	private static class PersonIcon implements javax.swing.Icon
	{
		@Override
		public void paintIcon(java.awt.Component c, java.awt.Graphics g, int x, int y)
		{
			java.awt.Graphics2D g2 = (java.awt.Graphics2D) g.create();
			g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(HIGHLIGHT);
			g2.setStroke(new java.awt.BasicStroke(2f));
			g2.drawOval(x + 7, y + 1, 10, 10);
			g2.drawArc(x + 1, y + 13, 22, 20, 0, 180);
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return 24;
		}

		@Override
		public int getIconHeight()
		{
			return 24;
		}
	}
}

package com.asgardians;

import java.util.Arrays;
import java.util.Locale;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.client.util.QuantityFormatter;

/** Turns the member's profile into the words the Connection card shows. */
final class ProfileText
{
	/** The ranks earned over time. Staff and honorary ranks aren't on this ladder, so they have no "next rank". */
	private static final Set<String> LADDER = Set.of("opal", "sapphire", "emerald", "ruby", "diamond", "dragonstone",
		"onyx", "zenyte");

	private ProfileText()
	{
	}

	/** "deputy_owner" becomes "Deputy Owner", "og_gamer" becomes "OG Gamer". */
	static String rank(String rank)
	{
		if (rank == null || rank.isEmpty())
		{
			return "Unranked";
		}
		return Arrays.stream(rank.split("[_ ]+"))
			.map(word -> word.equalsIgnoreCase("og") ? "OG"
				: word.substring(0, 1).toUpperCase(Locale.UK) + word.substring(1).toLowerCase(Locale.UK))
			.collect(Collectors.joining(" "));
	}

	/** 976 days becomes "2y 8m", the way the website's member list shows it. */
	static String time(int days)
	{
		if (days < 30)
		{
			return days + "d";
		}
		int years = days / 365;
		int months = (days % 365) / 30;
		if (years == 0)
		{
			return months + "m";
		}
		return months == 0 ? years + "y" : years + "y " + months + "m";
	}

	static String amount(long value)
	{
		return QuantityFormatter.quantityToStackSize(value);
	}

	/** How to link Discord, or null when it's already linked. */
	static String discordHelp(ClanData.Me me)
	{
		if (me.isDiscordLinked())
		{
			return null;
		}
		if (me.getDiscordHelp() != null)
		{
			return me.getDiscordHelp();
		}
		return "To link Discord, use the /asg link command in any of the Asgardians Clan Discord channels.";
	}

	/** What's left for the next rank, or null when the member isn't on the ladder or there's nothing above them. */
	static String nextRank(ClanData.Me me)
	{
		ClanData.NextRank next = me.getNextRank();
		if (next == null || next.getName() == null || me.getRank() == null
			|| !LADDER.contains(me.getRank().toLowerCase(Locale.UK)))
		{
			return null;
		}
		long credit = next.getCreditRemaining() != null ? next.getCreditRemaining() : 0;
		int days = next.getDaysRemaining() != null ? next.getDaysRemaining() : 0;
		if (credit <= 0 && days <= 0)
		{
			return "Ready for " + rank(next.getName()) + ". Staff will promote you.";
		}
		StringBuilder left = new StringBuilder();
		if (credit > 0)
		{
			left.append(amount(credit)).append(" credit");
		}
		if (days > 0)
		{
			left.append(left.length() > 0 ? " and " : "").append(days).append(days == 1 ? " day" : " days");
		}
		return "Next rank " + rank(next.getName()) + ": " + left + " to go";
	}
}

package com.asgardians;

import java.util.List;
import java.util.UUID;
import lombok.Data;

/**
 * One generic drop-recorder record. The server decides what each record counts for (drops page, clog page, events),
 * so the plugin records what happened and nothing more. Null fields are left out of the JSON.
 */
@Data
class Record
{
	enum Type
	{
		loot,
		pet,
		clog,
		pb,
		death,
		egg,
		/** A kill count message, for total KC and KC bingo tasks. */
		kc,
		/** The member's XP in each skill, for XP bingo tasks and leaderboards. */
		xp,
		/** A finished quest speedrun, for medal bingo tasks. */
		speedrun
	}

	/** Kc records: the kill's own time, when the game showed one (a PB or not). */
	@Data
	static class KillTime
	{
		private final double seconds;
		/** Game ticks, when precise timing is on. */
		private final Integer ticks;
		private final boolean precise;
		/** "1" for solo, "2"…"8", "11-15", "24+"; null when unknown. */
		private final String teamSize;
	}

	/** Speedrun records: the quest, the run's time and the member's best, in seconds. */
	@Data
	static class Speedrun
	{
		private final String quest;
		private final Double seconds;
		private final Double bestSeconds;
		/** The game said this run was a new personal best. */
		private final boolean personalBest;
	}

	/** Egg records: a handegg thrown by one player and caught by another. One of them is the player. */
	@Data
	static class Egg
	{
		private final String thrower;
		private final String target;
	}

	@Data
	static class Source
	{
		private final String name;
		private final Integer npcId;
		private Integer kc;
	}

	@Data
	static class Item
	{
		private final int id;
		private final String name;
		private final int qty;
		private final long gePrice;
	}

	private final String id = UUID.randomUUID().toString();
	private final Type type;
	/** ISO-8601 UTC time the event happened in game. */
	private final String at;
	private final int world;

	private Source source;
	private List<Item> items;
	/** How many players were in the instance, including the player. Only set for group content; never names. */
	private Integer partySize;

	/** Pet records: the pet's name from the clan broadcast, when one arrived. */
	private String petName;
	private Boolean duplicate;

	/** Clog records. */
	private String itemName;
	private Integer itemId;
	private Integer completed;

	/** PB records. */
	private PersonalBest pb;

	/** Death records. */
	private Death death;

	/** Egg records. */
	private Egg egg;

	/** XP records: XP by skill name ("Attack", ...), and the total. */
	private java.util.Map<String, Integer> xp;
	private Long totalXp;

	/** Speedrun records. */
	private Speedrun speedrun;

	/** Kc records: the kill's time, when the game showed one. */
	private KillTime time;

	/** True when a screenshot is uploaded with this record. */
	private boolean screenshot;

	/** Total GE value of the items, used for screenshot rules and the panel. Not sent. */
	transient long totalValue;
	/** Epoch millis when the record was created. Not sent. */
	transient long createdMillis;
	/** Still waiting for its screenshot; the uploader holds it back until it arrives or times out. Not sent. */
	transient volatile boolean awaitingScreenshot;

	String describe()
	{
		switch (type)
		{
			case pet:
				return "Pet" + (petName != null ? ": " + petName : "");
			case clog:
				return "Clog: " + itemName;
			case pb:
				return "PB: " + (pb != null ? pb.display() : "");
			case egg:
				return egg == null ? "Egg" : "Egg: " + egg.getThrower() + " egged " + egg.getTarget();
			case kc:
				return "KC: " + (source != null ? source.getName() + " " + source.getKc() : "");
			case xp:
				return "XP: " + (totalXp != null ? String.format("%,d", totalXp) + " total" : "");
			case speedrun:
				return "Speedrun: " + (speedrun != null ? speedrun.getQuest() : "");
			case death:
				if (death == null || death.getKiller() == null || death.getKiller().getName() == null)
				{
					return "Death";
				}
				return "Death: " + death.getKiller().getName();
			default:
				if (items == null || items.isEmpty())
				{
					return "Loot";
				}
				Item best = items.get(0);
				for (Item item : items)
				{
					if ((long) item.getQty() * item.getGePrice() > (long) best.getQty() * best.getGePrice())
					{
						best = item;
					}
				}
				return best.getName() + (source != null ? " (" + source.getName() + ")" : "");
		}
	}
}

package com.asgardians;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;

/**
 * Records waiting to be sent, plus the last 20 for the panel. Thread-safe: the client thread adds, the upload thread drains.
 */
class RecordQueue
{
	static final int MAX_QUEUED = 1000;
	static final int BATCH_SIZE = 50;
	static final int HISTORY = 20;
	/** How long a record waits for its screenshot before going without one. */
	static final long SCREENSHOT_WAIT_MILLIS = 10_000;

	enum Status
	{
		QUEUED,
		SENT,
		/** Not sent yet; will retry. */
		FAILED,
		/** The server refused this record; it won't be sent again. */
		REJECTED
	}

	static class Entry
	{
		final Record record;
		volatile Status status = Status.QUEUED;
		/** The server's reason, for rejected records. */
		volatile String reason;

		Entry(Record record)
		{
			this.record = record;
		}
	}

	private final Deque<Record> pending = new ArrayDeque<>();
	/**
	 * After the server rejects a batch, its records are retried one per batch so only the bad one is dropped. This many
	 * of the next batches are single records.
	 */
	private int sendSingly;
	private final Map<String, byte[]> screenshots = new HashMap<>();
	private final LinkedList<Entry> history = new LinkedList<>();
	private final Map<String, Entry> historyById = new HashMap<>();

	synchronized void add(Record record)
	{
		if (pending.size() >= MAX_QUEUED)
		{
			Record dropped = pending.pollFirst();
			if (dropped != null)
			{
				screenshots.remove(dropped.getId());
			}
		}
		pending.addLast(record);
		Entry entry = new Entry(record);
		history.addFirst(entry);
		historyById.put(record.getId(), entry);
		while (history.size() > HISTORY)
		{
			historyById.remove(history.removeLast().record.getId());
		}
	}

	/** The record goes without a picture, straight away rather than after the wait. */
	synchronized void noScreenshot(String recordId)
	{
		for (Record record : pending)
		{
			if (record.getId().equals(recordId))
			{
				record.awaitingScreenshot = false;
				record.setScreenshot(false);
				return;
			}
		}
	}

	synchronized void attachScreenshot(String recordId, byte[] png)
	{
		for (Record record : pending)
		{
			if (record.getId().equals(recordId))
			{
				screenshots.put(recordId, png);
				record.awaitingScreenshot = false;
				return;
			}
		}
	}

	/**
	 * Takes the next batch, oldest first. A record still waiting for its screenshot stops the batch there, so records stay
	 * in order, unless it has waited too long, in which case it goes without one.
	 */
	synchronized List<Record> takeBatch(long now)
	{
		List<Record> batch = new ArrayList<>();
		int limit = sendSingly > 0 ? 1 : BATCH_SIZE;
		while (!pending.isEmpty() && batch.size() < limit)
		{
			Record next = pending.peekFirst();
			if (next.awaitingScreenshot)
			{
				if (now - next.createdMillis < SCREENSHOT_WAIT_MILLIS)
				{
					break;
				}
				next.awaitingScreenshot = false;
				next.setScreenshot(false);
			}
			batch.add(pending.pollFirst());
		}
		if (!batch.isEmpty() && sendSingly > 0)
		{
			sendSingly--;
		}
		return batch;
	}

	/**
	 * The server refused a batch it couldn't accept. A single record is dropped and marked rejected; a larger batch goes
	 * back to be retried one record at a time, so good records aren't lost with a bad one.
	 *
	 * @return true when the batch was put back to retry singly, false when its one record was dropped
	 */
	synchronized boolean rejected(List<Record> batch, String reason)
	{
		if (batch.size() > 1)
		{
			for (int i = batch.size() - 1; i >= 0; i--)
			{
				pending.addFirst(batch.get(i));
			}
			sendSingly = Math.max(sendSingly, batch.size());
			mark(batch, Status.FAILED);
			return true;
		}
		for (Record record : batch)
		{
			screenshots.remove(record.getId());
			Entry entry = historyById.get(record.getId());
			if (entry != null)
			{
				entry.status = Status.REJECTED;
				entry.reason = reason;
			}
		}
		return false;
	}

	synchronized Map<String, byte[]> screenshotsFor(List<Record> batch)
	{
		Map<String, byte[]> out = new HashMap<>();
		for (Record record : batch)
		{
			byte[] png = screenshots.get(record.getId());
			if (png != null && record.isScreenshot())
			{
				out.put(record.getId(), png);
			}
		}
		return out;
	}

	/** Puts a failed batch back at the front, in its original order. */
	synchronized void requeue(List<Record> batch)
	{
		for (int i = batch.size() - 1; i >= 0; i--)
		{
			pending.addFirst(batch.get(i));
		}
		mark(batch, Status.FAILED);
	}

	synchronized void sent(List<Record> batch)
	{
		for (Record record : batch)
		{
			screenshots.remove(record.getId());
		}
		mark(batch, Status.SENT);
	}

	synchronized int size()
	{
		return pending.size();
	}

	synchronized List<Entry> recent()
	{
		return Collections.unmodifiableList(new ArrayList<>(history));
	}

	synchronized void clear()
	{
		pending.clear();
		screenshots.clear();
	}

	private void mark(List<Record> batch, Status status)
	{
		for (Record record : batch)
		{
			Entry entry = historyById.get(record.getId());
			if (entry != null)
			{
				entry.status = status;
			}
		}
	}
}

package com.asgardians;

import lombok.Data;

/** Settings served by GET /api/v1/plugin/config. The defaults apply until the server answers, or if it can't be reached. */
@Data
class ServerSettings
{
	@Data
	static class Screenshots
	{
		private long minLootValue = 1_000_000;
		private boolean pets = true;
		private boolean clog = true;
		private boolean pbs = true;
		private boolean deaths = true;
		/** Item IDs that always get a screenshot whatever they're worth, such as items a live event is watching for. */
		private java.util.Set<Integer> watch = java.util.Set.of();

		/** Loot gets a screenshot when it's valuable enough or includes a watched item. */
		boolean wantsLoot(Record record)
		{
			return record.totalValue >= minLootValue || watched(record);
		}

		/** The record includes an item on the watch list. */
		boolean watched(Record record)
		{
			if (watch != null && record.getItems() != null)
			{
				for (Record.Item item : record.getItems())
				{
					if (watch.contains(item.getId()))
					{
						return true;
					}
				}
			}
			return false;
		}
	}

	private Screenshots screenshots = new Screenshots();
	/** Stops all sending without a hub update. */
	private boolean killSwitch;
	/** Oldest plugin version the server still accepts. */
	private String minVersion;
}

package com.asgardians;

import static com.asgardians.PanelParts.Card;
import static com.asgardians.PanelParts.QUIET;
import static com.asgardians.PanelParts.TEXT;
import static com.asgardians.PanelParts.addCard;
