package com.asgardians;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class PersonalBestTest
{
	@Test
	public void splitsTeamSizeFromRuneLiteKeys()
	{
		PersonalBest solo = PersonalBest.of("theatre of blood solo", 1500.0);
		assertEquals("theatre of blood", solo.getBoss());
		assertEquals("1", solo.getTeamSize());

		PersonalBest three = PersonalBest.of("chambers of xeric challenge mode 3 players", 1800.6);
		assertEquals("chambers of xeric challenge mode", three.getBoss());
		assertEquals("3", three.getTeamSize());

		assertEquals("11-15", PersonalBest.of("chambers of xeric 11-15 players", 2000).getTeamSize());
		assertEquals("24+", PersonalBest.of("chambers of xeric 24+ players", 2000).getTeamSize());

		PersonalBest vorkath = PersonalBest.of("vorkath", 60.6);
		assertEquals("vorkath", vorkath.getBoss());
		assertNull(vorkath.getTeamSize());
	}

	@Test
	public void preciseTimesGetTicks()
	{
		PersonalBest precise = PersonalBest.of("vorkath", 84.6);
		assertTrue(precise.isPrecise());
		assertEquals(Integer.valueOf(141), precise.getTicks());
		assertEquals("vorkath 1:24.60", precise.display());

		PersonalBest whole = PersonalBest.of("vorkath", 85.0);
		assertFalse(whole.isPrecise());
		assertNull(whole.getTicks());
		assertEquals("vorkath 1:25", whole.display());

		assertEquals("tzkal-zuk 1:02:03.60", PersonalBest.of("tzkal-zuk", 3723.6).display());
	}

	@Test
	public void ignoresUnusableValues()
	{
		assertNull(PersonalBest.parse("vorkath", "abc"));
		assertNull(PersonalBest.parse("vorkath", "0"));
		assertNull(PersonalBest.parse("vorkath", null));
	}

	private static PbTracker tracker(Map<String, String> store)
	{
		return new PbTracker(new PbTracker.Store()
		{
			@Override
			public List<String> keys()
			{
				return List.copyOf(store.keySet());
			}

			@Override
			public String value(String key)
			{
				return store.get(key);
			}

			@Override
			public Integer killCount(String boss)
			{
				return "vorkath".equals(boss) ? 512 : null;
			}
		});
	}

	@Test
	public void changeAfterNewPbMessageIsSentLive()
	{
		PbTracker pbs = tracker(Map.of());
		pbs.chatMessage("Fight duration: 1:24.60 (new personal best)", 1_000);
		PersonalBest pb = pbs.changed("vorkath", "84.6", 1_100);
		assertTrue(pb.isNewPb());
		assertEquals(Integer.valueOf(512), pb.getKc());
		assertFalse(pbs.syncDue(100_000));
	}

	@Test
	public void otherChangesWaitForOneFullSync()
	{
		PbTracker pbs = tracker(Map.of());
		assertNull(pbs.changed("tzkal-zuk", "3723.6", 1_000));
		assertNull(pbs.changed("chambers of xeric 3 players", "1800", 2_000));
		assertFalse(pbs.syncDue(2_000 + PbTracker.SYNC_DEBOUNCE_MILLIS - 1));
		assertTrue(pbs.syncDue(2_000 + PbTracker.SYNC_DEBOUNCE_MILLIS));
		pbs.syncStarted();
		assertFalse(pbs.syncDue(1_000_000));
	}

	@Test
	public void oldNewPbMessageDoesNotCount()
	{
		PbTracker pbs = tracker(Map.of());
		pbs.chatMessage("Fight duration: 1:24.60 (new personal best)", 1_000);
		assertNull(pbs.changed("vorkath", "84.6", 1_000 + PbTracker.NEW_PB_WINDOW_MILLIS + 1));
	}

	@Test
	public void snapshotReadsWholeStoreWithKillCounts()
	{
		Map<String, String> store = new LinkedHashMap<>();
		store.put("vorkath", "84.6");
		store.put("theatre of blood 4 players", "1200.0");
		store.put("broken", "nope");
		List<PersonalBest> all = tracker(store).snapshot();
		assertEquals(2, all.size());
		assertEquals(Integer.valueOf(512), all.get(0).getKc());
		assertFalse(all.get(0).isNewPb());
		assertEquals("4", all.get(1).getTeamSize());
	}
}

package com.asgardians;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import com.google.gson.Gson;
import org.junit.Test;

public class ProfileTextTest
{
	private static ClanData.Me me(String rank, Long credit, Integer days)
	{
		ClanData.Me me = new ClanData.Me();
		me.setRank(rank);
		ClanData.NextRank next = new ClanData.NextRank();
		next.setName("Sapphire");
		next.setCreditRemaining(credit);
		next.setDaysRemaining(days);
		me.setNextRank(next);
		return me;
	}

	@Test
	public void ranksReadLikeTheWebsite()
	{
		assertEquals("Deputy Owner", ProfileText.rank("deputy_owner"));
		assertEquals("Opal", ProfileText.rank("opal"));
		assertEquals("OG Gamer", ProfileText.rank("og_gamer"));
		assertEquals("Unranked", ProfileText.rank(null));
	}

	@Test
	public void timeInClan()
	{
		assertEquals("12d", ProfileText.time(12));
		assertEquals("5m", ProfileText.time(150));
		assertEquals("2y 8m", ProfileText.time(976));
		assertEquals("1y", ProfileText.time(365));
	}

	@Test
	public void nextRankIsOnlyForTheLadder()
	{
		assertNull("staff aren't on the ladder", ProfileText.nextRank(me("deputy_owner", 20_000_000L, 0)));
		assertEquals("Next rank Sapphire: 20M credit to go", ProfileText.nextRank(me("opal", 20_000_000L, 0)));
		assertEquals("Next rank Sapphire: 20M credit and 3 days to go", ProfileText.nextRank(me("opal", 20_000_000L, 3)));
		assertEquals("Next rank Sapphire: 1 day to go", ProfileText.nextRank(me("opal", 0L, 1)));
		assertEquals("Ready for Sapphire. Staff will promote you.", ProfileText.nextRank(me("opal", 0L, 0)));
	}

	@Test
	public void discordHelpIsOnlyForUnlinkedMembers()
	{
		ClanData.Me me = new ClanData.Me();
		me.setRsn("Rozzle");
		assertEquals("To link Discord, use the /asg link command in any of the Asgardians Clan Discord channels.",
			ProfileText.discordHelp(me));

		me.setDiscordHelp("Ask staff to link you.");
		assertEquals("Ask staff to link you.", ProfileText.discordHelp(me));

		me.setDiscordLinked(true);
		assertNull(ProfileText.discordHelp(me));
	}

	@Test
	public void memberIsListedBelowTheTopOnlyWhenOutsideIt()
	{
		String json = "{\"boards\":[{\"title\":\"Boss of the Week: Vorkath\",\"endsAt\":\"2026-11-02T13:00:00Z\",\"rows\":["
			+ "{\"rank\":1,\"rsn\":\"Str4tty\",\"value\":\"412 kills\"}],\"me\":{\"rank\":14,\"rsn\":\"Rozzle\",\"value\":\"31 kills\"}},"
			+ "{\"title\":\"Clan credit\",\"subtitle\":\"November so far\",\"rows\":[{\"rank\":1,\"rsn\":\"Rozzle\",\"value\":\"412M\"}],"
			+ "\"me\":{\"rank\":1,\"rsn\":\"Rozzle\",\"value\":\"412M\"}},"
			+ "{\"title\":\"Drops\",\"rows\":[]}]}";
		java.util.List<ClanData.Leaderboard> boards = new Gson().fromJson(json, ClanData.LeaderboardList.class).getBoards();
		assertEquals(Integer.valueOf(14), boards.get(0).rowBelowTop().getRank());
		assertEquals(java.time.Instant.parse("2026-11-02T13:00:00Z"), boards.get(0).ends());
		assertNull(boards.get(1).rowBelowTop());
		assertNull(boards.get(2).rowBelowTop());
	}

	@Test
	public void readsTheTestServersReply()
	{
		String json = "{\"rsn\":\"Rozzle\",\"rank\":\"deputy_owner\",\"joinedAt\":\"2024-02-29T15:49:47.3633333\",\"daysInClan\":976,"
			+ "\"splitCredit\":0,\"discordLinked\":true,\"recommendedRank\":\"Opal\",\"nextRank\":{\"name\":\"Sapphire\",\"minDays\":14,"
			+ "\"minCredit\":20000000,\"daysRemaining\":0,\"creditRemaining\":20000000,\"progress\":0,\"daysProgress\":1,\"creditProgress\":0},"
			+ "\"accountType\":\"IRONMAN\",\"held\":false}";
		ClanData.Me me = new Gson().fromJson(json, ClanData.Me.class);
		assertEquals(Integer.valueOf(976), me.getDaysInClan());
		assertEquals(Long.valueOf(0), me.getSplitCredit());
		assertEquals(Long.valueOf(20_000_000), me.getNextRank().getCreditRemaining());
		assertNull(me.getDrops());
	}
}

package com.asgardians;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.List;
import org.junit.Test;

public class RecordQueueTest
{
	private static Record record(long created)
	{
		Record record = new Record(Record.Type.pet, "2026-10-22T12:00:00Z", 416);
		record.createdMillis = created;
		return record;
	}

	@Test
	public void batchStopsAtRecordWaitingForScreenshot()
	{
		RecordQueue queue = new RecordQueue();
		Record first = record(0);
		Record waiting = record(0);
		waiting.setScreenshot(true);
		waiting.awaitingScreenshot = true;
		Record third = record(0);
		queue.add(first);
		queue.add(waiting);
		queue.add(third);

		assertEquals(List.of(first), queue.takeBatch(1_000));
		queue.attachScreenshot(waiting.getId(), new byte[]{1});
		List<Record> batch = queue.takeBatch(1_000);
		assertEquals(List.of(waiting, third), batch);
		assertEquals(1, queue.screenshotsFor(batch).size());
	}

	@Test
	public void screenshotTimesOut()
	{
		RecordQueue queue = new RecordQueue();
		Record waiting = record(0);
		waiting.setScreenshot(true);
		waiting.awaitingScreenshot = true;
		queue.add(waiting);
		assertTrue(queue.takeBatch(1_000).isEmpty());
		List<Record> batch = queue.takeBatch(RecordQueue.SCREENSHOT_WAIT_MILLIS + 1);
		assertEquals(1, batch.size());
		assertFalse(batch.get(0).isScreenshot());
	}

	@Test
	public void noScreenshotReleasesTheRecordStraightAway()
	{
		RecordQueue queue = new RecordQueue();
		Record waiting = record(0);
		waiting.setScreenshot(true);
		waiting.awaitingScreenshot = true;
		queue.add(waiting);
		queue.noScreenshot(waiting.getId());
		List<Record> batch = queue.takeBatch(0);
		assertEquals(List.of(waiting), batch);
		assertFalse(batch.get(0).isScreenshot());
		assertTrue(queue.screenshotsFor(batch).isEmpty());
	}

	@Test
	public void failedBatchGoesBackInOrder()
	{
		RecordQueue queue = new RecordQueue();
		Record a = record(0);
		Record b = record(0);
		queue.add(a);
		queue.add(b);
		List<Record> batch = queue.takeBatch(0);
		queue.requeue(batch);
		assertEquals(List.of(a, b), queue.takeBatch(0));
		assertEquals(RecordQueue.Status.FAILED, queue.recent().get(0).status);
	}

	@Test
	public void rejectedBatchIsRetriedOneByOneAndOnlyTheBadRecordIsDropped()
	{
		RecordQueue queue = new RecordQueue();
		Record good1 = record(0);
		Record bad = record(0);
		Record good2 = record(0);
		queue.add(good1);
		queue.add(bad);
		queue.add(good2);

		List<Record> batch = queue.takeBatch(0);
		assertEquals(3, batch.size());
		assertTrue(queue.rejected(batch, "records[1].type must be loot, pet or clog."));

		List<Record> first = queue.takeBatch(0);
		assertEquals(List.of(good1), first);
		queue.sent(first);

		List<Record> second = queue.takeBatch(0);
		assertEquals(List.of(bad), second);
		assertFalse(queue.rejected(second, "type must be loot, pet or clog."));

		assertEquals(List.of(good2), queue.takeBatch(0));
		assertEquals(0, queue.size());

		RecordQueue.Entry badEntry = queue.recent().get(1);
		assertEquals(RecordQueue.Status.REJECTED, badEntry.status);
		assertEquals("type must be loot, pet or clog.", badEntry.reason);
		assertEquals(RecordQueue.Status.SENT, queue.recent().get(2).status);
	}

	@Test
	public void batchesGoBackToFullSizeAfterIsolating()
	{
		RecordQueue queue = new RecordQueue();
		for (int i = 0; i < 2; i++)
		{
			queue.add(record(0));
		}
		queue.rejected(queue.takeBatch(0), "bad");
		queue.sent(queue.takeBatch(0));
		queue.sent(queue.takeBatch(0));
		for (int i = 0; i < 5; i++)
		{
			queue.add(record(0));
		}
		assertEquals(5, queue.takeBatch(0).size());
	}

	@Test
	public void historyKeepsLastTwenty()
	{
		RecordQueue queue = new RecordQueue();
		for (int i = 0; i < 25; i++)
		{
			queue.add(record(0));
		}
		assertEquals(RecordQueue.HISTORY, queue.recent().size());
	}
}

package com.asgardians;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class SignupFormTest
{
	private static ClanData.Field field(String key, String type, boolean required)
	{
		ClanData.Field f = new ClanData.Field();
		f.setKey(key);
		f.setLabel(key);
		f.setType(type);
		f.setRequired(required);
		return f;
	}

	private static final List<ClanData.Field> BINGO_FORM;

	static
	{
		ClanData.Field hours = field("hoursPerDay", "number", true);
		hours.setMin(0.0);
		hours.setMax(24.0);
		ClanData.Field team = field("team", "choice", false);
		team.setOptions(List.of("Any", "Team 1", "Team 2"));
		BINGO_FORM = List.of(hours, field("timezone", "timezone", true), field("caTier", "caTier", false), team,
			field("bosses", "multi", false), field("notes", "text", false));
	}

	private static Map<String, Object> answers(Object... keyValues)
	{
		Map<String, Object> map = new LinkedHashMap<>();
		for (int i = 0; i < keyValues.length; i += 2)
		{
			map.put((String) keyValues[i], keyValues[i + 1]);
		}
		return map;
	}

	@Test
	public void validAnswersAreTypedAndEmptyOptionalsLeftOut()
	{
		SignupForm.Checked checked = SignupForm.check(BINGO_FORM, answers("hoursPerDay", "4", "timezone", "Europe/London",
			"caTier", "Elite", "team", "", "bosses", List.of("Nex", "Nightmare"), "notes", ""));
		assertNull(checked.getError());
		assertEquals(4L, checked.getAnswers().get("hoursPerDay"));
		assertEquals("Europe/London", checked.getAnswers().get("timezone"));
		assertEquals(List.of("Nex", "Nightmare"), checked.getAnswers().get("bosses"));
		assertTrue(!checked.getAnswers().containsKey("team") && !checked.getAnswers().containsKey("notes"));
	}

	@Test
	public void requiredMissingIsRefused()
	{
		assertEquals("hoursPerDay is required.",
			SignupForm.check(BINGO_FORM, answers("hoursPerDay", "", "timezone", "Europe/London")).getError());
	}

	@Test
	public void numbersMustBeNumbersInRange()
	{
		assertEquals("hoursPerDay must be a number.",
			SignupForm.check(BINGO_FORM, answers("hoursPerDay", "lots", "timezone", "UTC")).getError());
		assertEquals("hoursPerDay must be between 0 and 24.",
			SignupForm.check(BINGO_FORM, answers("hoursPerDay", "30", "timezone", "UTC")).getError());
		assertEquals(2.5, SignupForm.check(BINGO_FORM, answers("hoursPerDay", "2.5", "timezone", "UTC")).getAnswers().get("hoursPerDay"));
	}

	@Test
	public void timezoneAndChoiceAreChecked()
	{
		assertTrue(SignupForm.check(BINGO_FORM, answers("hoursPerDay", "1", "timezone", "Mars/Olympus")).getError()
			.contains("isn't a timezone"));
		assertTrue(SignupForm.check(BINGO_FORM, answers("hoursPerDay", "1", "timezone", "UTC", "team", "Team 9")).getError()
			.contains("pick one of the options"));
	}

	@Test
	public void caTierFromPointsAndThresholds()
	{
		int[] thresholds = {41, 161, 416, 1064, 1904, 2630};
		assertEquals("None", SignupForm.caTier(10, thresholds));
		assertEquals("Hard", SignupForm.caTier(500, thresholds));
		assertEquals("Grandmaster", SignupForm.caTier(2700, thresholds));
		assertEquals("None", SignupForm.caTier(500, new int[]{0, 0, 0, 0, 0, 0}));
	}
}

